import { GameState, GamePhase, Action, Outcome } from '../src/state/GameState.js';
import { VEGAS_STRIP_RULES, DealerHitRule, SurrenderRule, createCustomRules } from '../src/rules/Rules.js';
import { Card, Rank, Suit } from '../src/core/Card.js';

// Helpers
function buildShoe(playerCards: Card[], dealerCards: Card[], extra: Card[] = []) {
  // dealInitial order: P1, D1(down), P2, D2(up)
  // Array is popped from end
  const cards = [...extra].reverse(); // extra cards to be dealt later
  cards.push(dealerCards[1]); // D-up
  cards.push(playerCards[1]); // P2
  cards.push(dealerCards[0]); // D-hole
  cards.push(playerCards[0]); // P1
  return cards;
}

describe('GameState', () => {
  it('should initialize with rules', () => {
    const game = new GameState(VEGAS_STRIP_RULES);
    expect(game.rules.variant).toBe('Vegas Strip');
    expect(game.phase).toBe(GamePhase.Idle);
    expect(game.playerBankroll).toBe(1000);
  });

  it('should place bet and deal initially', () => {
    const game = new GameState(VEGAS_STRIP_RULES);
    game.resetRound();
    game.placeBet(50);
    game.dealInitial();
    expect(game.dealerHand.cards).toHaveLength(2);
    expect(game.playerHands[0].cards).toHaveLength(2);
  });

  it('should offer insurance on dealer ace', () => {
    const game = new GameState(VEGAS_STRIP_RULES);
    game.resetRound();
    game.placeBet(10);
    game.shoe.cards = buildShoe(
      [new Card(Rank.Two, Suit.Hearts), new Card(Rank.Two, Suit.Spades)],
      [new Card(Rank.Three, Suit.Clubs), new Card(Rank.Ace, Suit.Spades)]
    );
    game.dealInitial();
    expect(game.insuranceOffered).toBe(true);
  });

  it('should resolve blackjack immediately if dealer does not have ace', () => {
    const game = new GameState(VEGAS_STRIP_RULES);
    game.resetRound();
    game.placeBet(10);
    game.shoe.cards = buildShoe(
      [new Card(Rank.Ace, Suit.Hearts), new Card(Rank.King, Suit.Spades)],
      [new Card(Rank.Three, Suit.Clubs), new Card(Rank.Nine, Suit.Spades)]
