    expect(game.phase).toBe(GamePhase.RoundOver);
  });

  it('should handle split', () => {
    const game = new GameState(VEGAS_STRIP_RULES);
    game.resetRound();
    game.placeBet(10);
    game.shoe.cards = buildShoe(
      [new Card(Rank.Eight, Suit.Clubs), new Card(Rank.Eight, Suit.Hearts)],
      [new Card(Rank.Three, Suit.Clubs), new Card(Rank.Nine, Suit.Spades)],
      [new Card(Rank.Two, Suit.Spades), new Card(Rank.Two, Suit.Diamonds)]
    );
    game.dealInitial();
    game.split();
    expect(game.playerHands).toHaveLength(2);
