import { describe, it, expect } from 'vitest';
import { Suit, Value, createCard, cardValuePoints, isFaceCard, bestHandValue, hardValue } from './card.js';

describe('createCard', () => {
  it('should create a card with given suit, value, and faceUp state', () => {
    const card = createCard(Suit.Hearts, Value.Ace, true);
    expect(card.suit).toBe(Suit.Hearts);
    expect(card.value).toBe(Value.Ace);
    expect(card.faceUp).toBe(true);
  });
});

describe('cardValuePoints', () => {
  it('should return [1, 11] for Ace', () => {
    expect(cardValuePoints(Value.Ace)).toEqual([1, 11]);
  });

  it('should return [10] for face cards and ten', () => {
    expect(cardValuePoints(Value.Ten)).toEqual([10]);
    expect(cardValuePoints(Value.Jack)).toEqual([10]);
    expect(cardValuePoints(Value.Queen)).toEqual([10]);
    expect(cardValuePoints(Value.King)).toEqual([10]);
  });

  it('should return correct point values for number cards', () => {
    expect(cardValuePoints(Value.Two)).toEqual([2]);
    expect(cardValuePoints(Value.Five)).toEqual([5]);
    expect(cardValuePoints(Value.Nine)).toEqual([9]);
  });
});

describe('isFaceCard', () => {
  it('should return true for Jack, Queen, King', () => {
    expect(isFaceCard(Value.Jack)).toBe(true);
    expect(isFaceCard(Value.Queen)).toBe(true);
    expect(isFaceCard(Value.King)).toBe(true);
  });

  it('should return false for number cards and Ace', () => {
    expect(isFaceCard(Value.Ace)).toBe(false);
    expect(isFaceCard(Value.Two)).toBe(false);
    expect(isFaceCard(Value.Ten)).toBe(false);
  });
});

describe('bestHandValue', () => {
  it('should compute best value for non-bust hands', () => {
    expect(bestHandValue([[10], [5]])).toBe(15);
  });

  it('should pick the highest non-bust total', () => {
    expect(bestHandValue([[1, 11], [9]])).toBe(20); // Ace=11 + 9 = 20
  });

  it('should return lowest total if all bust', () => {
    expect(bestHandValue([[10], [10], [10]])).toBe(30); // all bust, min is 30
  });

  it('should handle multiple aces', () => {
    expect(bestHandValue([[1, 11], [1, 11]])).toBe(12); // 1+1=2 or 1+11=12 or 11+1=12 or 11+11=22(>21) => best=12
  });

  it('should return 21 for blackjack', () => {
    expect(bestHandValue([[1, 11], [10]])).toBe(21);
  });
});

