  1 | import { Card } from '../models/card.js';
  2 | import { Hand } from '../models/hand.js';
  3 | 
  4 | /**
  5 |  * ASCII card renderer - renders cards as bordered boxes side-by-side.
  6 |  *
  7 |  * Card box layout:
  8 |  * ┌──────────────┐
  9 |  * │ A          ♠ │
 10 |  * │              │
 11 |  * │      ♠       │
 12 |  * │              │
 13 |  * │ ♠          A │
 14 |  * └──────────────┘
 15 |  */
 16 | const CARD_TOP = '┌──────────────┐';
 17 | const CARD_EMPTY = '│              │';
 18 | 
 19 | /**
 20 |  * Build a single card rendered as ASCII lines.
 21 |  * Face-down cards show a shaded box.
 22 |  */
 23 | function buildCardLines(card: Card): string[] {
 24 |   if (!card.faceUp) {
 25 |     return [
 26 |       CARD_TOP,
 27 |       '│▓▓▓▓▓▓▓▓▓▓▓▓▓▓│',
 28 |       '│▓▓▓▓▓▓▓▓▓▓▓▓▓▓│',
 29 |       '│▓▓▓▓▓▓▓▓▓▓▓▓▓▓│',
 30 |       '│▓▓▓▓▓▓▓▓▓▓▓▓▓▓│',
 31 |       '└──────────────┘',
 32 |     ];
 33 |   }
 34 | 
 35 |   const rank = card.value.padEnd(2, ' ');
 36 |   const suit = card.suit;
 37 | 
 38 |   return [
 39 |     CARD_TOP,
 40 |     `│ ${rank}           │`,
 41 |     CARD_EMPTY,
 42 |     `│      ${suit}       │`,
 43 |     CARD_EMPTY,
 44 |     `│           ${rank.trim().padStart(2, ' ')} │`,
 45 |     '└──────────────┘',
 46 |   ];
 47 | }
 48 | 
 49 | /**
 50 |  * Compose multiple card boxes side-by-side into lines.
 51 |  */
 52 | function composeSideBySide(cards: Card[]): string[] {
 53 |   if (cards.length === 0) return ['(empty)'];
 54 | 
 55 |   const boxes = cards.map(buildCardLines);
 56 |   const height = Math.max(...boxes.map((b) => b.length));
 57 | 
 58 |   const rows: string[] = [];
 59 |   for (let r = 0; r < height; r++) {
 60 |     let row = '';
 61 |     for (const box of boxes) {
 62 |       row += (box[r] ?? '│              │') + '  ';
 63 |     }
 64 |     rows.push(row.replace(/\s+$/, ''));
 65 |   }
 66 |   return rows;
 67 | }
 68 | 
 69 | /**
 70 |  * Render a hand of cards as ASCII art with optional label.
 71 |  */
 72 | export function renderHand(cards: Card[], label = ''): string {
 73 |   const lines = composeSideBySide(cards);
 74 |   const output: string[] = [];
 75 |   if (label) output.push(label);
 76 |   output.push(...lines);
 77 |   output.push('');
 78 |   return output.join('\n');
 79 | }
 80 | 
 81 | /**
 82 |  * Render the full game table as ASCII art.
 83 |  */
 84 | export function renderTable(
 85 |   playerHands: Hand[],
 86 |   dealerHand: Hand,
 87 |   phase: string,
 88 | ): string {
 89 |   const sections: string[] = [];
 90 | 
 91 |   // Dealer section
 92 |   sections.push(`═══ DEALER ═══ (Phase: ${phase}) ═══`);
 93 |   sections.push(renderHand(dealerHand.getCards()));
 94 | 
 95 |   // Player section
 96 |   for (let i = 0; i < playerHands.length; i++) {
 97 |     const hand = playerHands[i];
 98 |     const valueText = hand.isBust
 99 |       ? 'BUST!'
100 |       : hand.isBlackjack
101 |         ? 'BLACKJACK!'
102 |         : `Value: ${hand.bestValue}`;
103 |     const label = `═══ HAND ${i + 1} ═══ Bet: $${hand.wager} ═══ (${valueText}) ═══`;
104 |     sections.push(label);
105 |     sections.push(renderHand(hand.getCards()));
106 |   }
107 | 
108 |   return sections.join('\n');
109 | }
110 | 
111 | /**
112 |  * Format count information as a single line.
113 |  */
114 | export function formatCountLine(
115 |   counts: Record<string, { running: number; true: number }>,
116 | ): string {
117 |   return Object.entries(counts)
118 |     .map(([name, c]) => `${name}: RC=${c.running}, TC=${c.true}`)
119 |     .join(' | ');
120 | }

