204 | // AvailableActions returns the list of valid actions for the active player hand.
205 | func (g *GameEngine) AvailableActions() []PlayerAction {
206 | 	if g.State != StatePlayerTurn {
207 | 		if g.State == StateInsuranceOffered {
208 | 			return []PlayerAction{ActionInsuranceAccept, ActionInsuranceDecline}
209 | 		}
210 | 		return nil
211 | 	}
212 | 
213 | 	hand := g.ActiveHand()
214 | 	if hand == nil || hand.Status != StatusInPlay {
215 | 		return nil
216 | 	}
217 | 
218 | 	actions := []PlayerAction{ActionHit, ActionStand}
219 | 
220 | 	// Double Down
221 | 	if hand.CanDouble() {
222 | 		canDoubleRule := true
223 | 		if hand.IsSplitHand && !g.Rules.DoubleAfterSplit {
224 | 			canDoubleRule = false
225 | 		}
226 | 		if canDoubleRule {
227 | 			tot := hand.Total()
228 | 			switch g.Rules.DoubleRestriction {
229 | 			case rules.Double9To11Only:
230 | 				if tot < 9 || tot > 11 {
231 | 					canDoubleRule = false
232 | 				}
233 | 			case rules.Double10Or11Only:
234 | 				if tot < 10 || tot > 11 {
235 | 					canDoubleRule = false
236 | 				}
237 | 			}
238 | 		}
239 | 		if canDoubleRule {
240 | 			actions = append(actions, ActionDouble)
241 | 		}
242 | 	}
243 | 
244 | 	// Split
245 | 	if hand.CanSplit() && len(g.PlayerHands) < g.Rules.MaxSplitHands {
246 | 		if hand.Cards[0].IsAce() {
247 | 			// Ace splitting restrictions
248 | 			if !hand.IsSplitHand || g.Rules.ResplitAces {
249 | 				actions = append(actions, ActionSplit)
250 | 			}
251 | 		} else {
252 | 			actions = append(actions, ActionSplit)
253 | 		}
254 | 	}
255 | 
256 | 	// Surrender
257 | 	if hand.CanSurrender() && g.Rules.Surrender == rules.SurrenderLate {
258 | 		actions = append(actions, ActionSurrender)
259 | 	}
260 | 
261 | 	return actions
262 | }
263 | 
264 | // ActiveHand returns the pointer to currently active player hand.
265 | func (g *GameEngine) ActiveHand() *Hand {
266 | 	if g.ActiveHandIdx >= 0 && g.ActiveHandIdx < len(g.PlayerHands) {
267 | 		return g.PlayerHands[g.ActiveHandIdx]
268 | 	}
269 | 	return nil
270 | }
271 | 
272 | // Step applies a player action to the active hand.
273 | func (g *GameEngine) Step(action PlayerAction) error {
274 | 	if g.State != StatePlayerTurn {
275 | 		if g.State == StateInsuranceOffered {
276 | 			if action == ActionInsuranceAccept {
277 | 				return g.Insurance(true)
278 | 			} else if action == ActionInsuranceDecline {
279 | 				return g.Insurance(false)
280 | 			}
281 | 		}
282 | 		return fmt.Errorf("action %s not allowed in state %s", action, g.State)
283 | 	}
284 | 
285 | 	hand := g.ActiveHand()
286 | 	if hand == nil || hand.Status != StatusInPlay {
287 | 		return errors.New("no active hand in play")
288 | 	}
289 | 
290 | 	switch action {
291 | 	case ActionHit:
292 | 		return g.actionHit(hand)
293 | 	case ActionStand:
294 | 		return g.actionStand(hand)
295 | 	case ActionDouble:
296 | 		return g.actionDouble(hand)
297 | 	case ActionSplit:
298 | 		return g.actionSplit(hand)
299 | 	case ActionSurrender:
300 | 		return g.actionSurrender(hand)
301 | 	default:
302 | 		return fmt.Errorf("invalid action: %s", action)
303 | 	}
304 | }
305 | 
306 | func (g *GameEngine) actionHit(hand *Hand) error {
307 | 	card := g.Shoe.Deal()
308 | 	hand.AddCard(card)
309 | 
310 | 	if hand.IsBusted() {
311 | 		hand.Status = StatusBusted
312 | 		return g.advanceToNextHand()
313 | 	}
314 | 
315 | 	if hand.Total() == 21 {
316 | 		hand.Status = StatusStood
317 | 		return g.advanceToNextHand()
318 | 	}
319 | 
320 | 	return nil
321 | }
322 | 
323 | func (g *GameEngine) actionStand(hand *Hand) error {
324 | 	hand.Status = StatusStood
325 | 	return g.advanceToNextHand()
326 | }
327 | 
328 | func (g *GameEngine) actionDouble(hand *Hand) error {
329 | 	if !hand.CanDouble() {
330 | 		return errors.New("cannot double this hand")
331 | 	}
332 | 
333 | 	hand.Bet *= 2
334 | 	hand.Doubled = true
335 | 	card := g.Shoe.Deal()
336 | 	hand.AddCard(card)
337 | 
338 | 	if hand.IsBusted() {
339 | 		hand.Status = StatusBusted
340 | 	} else {
341 | 		hand.Status = StatusDoubled
342 | 	}
343 | 
344 | 	return g.advanceToNextHand()
345 | }
346 | 
347 | func (g *GameEngine) actionSplit(hand *Hand) error {
348 | 	if !hand.CanSplit() || len(g.PlayerHands) >= g.Rules.MaxSplitHands {
349 | 		return errors.New("cannot split this hand")
350 | 	}
351 | 
352 | 	isAceSplit := hand.Cards[0].IsAce()
353 | 	card1 := hand.Cards[0]
354 | 	card2 := hand.Cards[1]
355 | 
356 | 	// First hand keeps card1, draws 1 new card
357 | 	hand.Cards = []cards.Card{card1}
358 | 	hand.IsSplitHand = true
359 | 	if isAceSplit {
360 | 		hand.FromSplitAces = true
361 | 	}
362 | 	newCard1 := g.Shoe.Deal()
363 | 	hand.AddCard(newCard1)
364 | 
365 | 	// Create second hand with card2, draws 1 new card
366 | 	newHand := NewHand(hand.Bet)
367 | 	newHand.Cards = []cards.Card{card2}
368 | 	newHand.IsSplitHand = true
369 | 	if isAceSplit {
370 | 		newHand.FromSplitAces = true
371 | 	}
372 | 	newCard2 := g.Shoe.Deal()
373 | 	newHand.AddCard(newCard2)
374 | 
375 | 	// Insert second hand right after current hand
376 | 	g.PlayerHands = append(g.PlayerHands[:g.ActiveHandIdx+1], append([]*Hand{newHand}, g.PlayerHands[g.ActiveHandIdx+1:]...)...)
377 | 
378 | 	// If splitting Aces and rule prohibits hitting split Aces, both stand automatically
379 | 	if isAceSplit && !g.Rules.HitSplitAces {
380 | 		hand.Status = StatusStood
381 | 		newHand.Status = StatusStood
382 | 		return g.advanceToNextHand()
383 | 	}
384 | 
385 | 	// If hand total is 21 after receiving card, auto stand
386 | 	if hand.Total() == 21 {
387 | 		hand.Status = StatusStood
388 | 		return g.advanceToNextHand()
389 | 	}
390 | 
391 | 	return nil
392 | }
393 | 
394 | func (g *GameEngine) actionSurrender(hand *Hand) error {
395 | 	if !hand.CanSurrender() || g.Rules.Surrender != rules.SurrenderLate {
396 | 		return errors.New("surrender is not permitted")
397 | 	}
398 | 
399 | 	hand.Status = StatusSurrendered
400 | 	return g.advanceToNextHand()
401 | }
402 | 
403 | func (g *GameEngine) advanceToNextHand() error {
404 | 	for i := g.ActiveHandIdx; i < len(g.PlayerHands); i++ {
405 | 		if g.PlayerHands[i].Status == StatusInPlay {
406 | 			g.ActiveHandIdx = i
407 | 			return nil
408 | 		}
409 | 	}
410 | 
411 | 	// All player hands resolved
412 | 	g.State = StateDealerTurn
413 | 	return g.playDealerTurn()
414 | }
415 | 
416 | func (g *GameEngine) playDealerTurn() error {
417 | 	// Reveal hole card if present, or deal dealer's 2nd card in European (ENHC) mode
418 | 	if g.HasHoleCard {
419 | 		g.DealerHand.AddCard(g.DealerHoleCard)
420 | 		g.HasHoleCard = false
421 | 	} else if len(g.DealerHand.Cards) == 1 {
422 | 		// In ENHC mode dealer draws 2nd card now
423 | 		g.DealerHand.AddCard(g.Shoe.Deal())
424 | 	}
425 | 
426 | 	// Check if all player hands busted or surrendered - if so, dealer doesn't need to draw further
427 | 	allDead := true
428 | 	for _, h := range g.PlayerHands {
429 | 		if h.Status != StatusBusted && h.Status != StatusSurrendered {
430 | 			allDead = false
431 | 			break
432 | 		}
433 | 	}
434 | 
435 | 	if !allDead {
436 | 		for {
437 | 			tot, isSoft := g.DealerHand.Score()
438 | 			if tot < 17 {
439 | 				c := g.Shoe.Deal()
440 | 				g.DealerHand.AddCard(c)
441 | 				continue
442 | 			}
443 | 			if tot == 17 && isSoft && g.Rules.DealerHitsSoft17 {
444 | 				c := g.Shoe.Deal()
445 | 				g.DealerHand.AddCard(c)
446 | 				continue
447 | 			}
448 | 			break
449 | 		}
450 | 	}
451 | 
452 | 	if g.DealerHand.IsBusted() {
453 | 		g.DealerHand.Status = StatusBusted
454 | 	} else if g.DealerHand.IsBlackjack() {
455 | 		g.DealerHand.Status = StatusBlackjack
456 | 	} else {
457 | 		g.DealerHand.Status = StatusStood
458 | 	}
459 | 
460 | 	g.resolveRound()
461 | 	return nil
462 | }
463 | 
464 | func (g *GameEngine) resolveRound() {
465 | 	g.State = StateRoundResolved
466 | 	dealerTotal := g.DealerHand.Total()
467 | 	dealerBJ := g.DealerHand.IsBlackjack()
468 | 	dealerBust := g.DealerHand.IsBusted()
469 | 
470 | 	for _, h := range g.PlayerHands {
471 | 		pTotal := h.Total()
472 | 		pBJ := h.IsBlackjack()
473 | 
474 | 		var netProfit float64
475 | 		var payout float64
476 | 
477 | 		// Process Insurance
478 | 		if h.InsuranceBet > 0 {
479 | 			if h.InsuranceWon {
480 | 				netProfit += h.InsuranceBet * 2.0 // Insurance pays 2:1
481 | 			} else {
482 | 				netProfit -= h.InsuranceBet
483 | 			}
484 | 		}
485 | 
486 | 		if h.Status == StatusSurrendered {
487 | 			payout = -0.5
488 | 			netProfit += -0.5 * h.Bet
489 | 		} else if h.Status == StatusBusted {
490 | 			payout = -1.0
491 | 			netProfit += -1.0 * h.Bet
492 | 		} else if dealerBJ {
493 | 			if pBJ {
494 | 				payout = 0.0 // Push
495 | 				netProfit += 0.0
496 | 			} else {
497 | 				payout = -1.0
498 | 				netProfit += -1.0 * h.Bet
499 | 			}
500 | 		} else if pBJ {
501 | 			// Natural player Blackjack wins payout ratio (e.g. 1.5x)
502 | 			bjMultiplier := float64(g.Rules.BlackjackPayout)
503 | 			payout = bjMultiplier
504 | 			netProfit += bjMultiplier * h.Bet
505 | 		} else if dealerBust {
506 | 			// Dealer busted, player not busted
507 | 			payout = 1.0
508 | 			netProfit += 1.0 * h.Bet
509 | 		} else {
510 | 			// Compare totals
511 | 			if pTotal > dealerTotal {
512 | 				payout = 1.0
513 | 				netProfit += 1.0 * h.Bet
514 | 			} else if pTotal < dealerTotal {
515 | 				payout = -1.0
516 | 				netProfit += -1.0 * h.Bet
517 | 			} else {
518 | 				payout = 0.0 // Push
519 | 				netProfit += 0.0
520 | 			}
521 | 		}
522 | 
523 | 		h.Payout = payout
524 | 		h.NetProfit = netProfit
525 | 	}
526 | }
527 | 
528 | // NetRoundProfit returns the aggregate profit/loss across all split hands and insurance.
529 | func (g *GameEngine) NetRoundProfit() float64 {
530 | 	var total float64
531 | 	for _, h := range g.PlayerHands {
532 | 		total += h.NetProfit
533 | 	}
534 | 	return total
535 | }
