102 | func TestGameEngine_BasicRoundFlows(t *testing.T) {
103 | 	rule := rules.VegasStrip()
104 | 	engine := NewGameEngine(rule, nil)
105 | 
106 | 	if engine.State != StateWaitingBet {
107 | 		t.Fatalf("Expected initial state StateWaitingBet, got %v", engine.State)
108 | 	}
109 | 
110 | 	// Invalid Bet
111 | 	if err := engine.StartRound(0); err == nil {
112 | 		t.Errorf("Expected error starting round with 0 bet")
113 | 	}
114 | 
115 | 	// Start valid round
116 | 	err := engine.StartRound(100)
117 | 	if err != nil {
118 | 		t.Fatalf("StartRound failed: %v", err)
119 | 	}
120 | 
121 | 	// Active hand
122 | 	if engine.ActiveHand() == nil {
123 | 		t.Fatalf("ActiveHand should not be nil")
124 | 	}
125 | 
126 | 	// If in StateInsuranceOffered, test declining insurance
127 | 	if engine.State == StateInsuranceOffered {
128 | 		actions := engine.AvailableActions()
129 | 		if len(actions) != 2 {
130 | 			t.Errorf("Expected 2 insurance actions, got %d", len(actions))
131 | 		}
132 | 		err = engine.Step(ActionInsuranceDecline)
133 | 		if err != nil {
134 | 			t.Fatalf("Declining insurance failed: %v", err)
135 | 		}
136 | 	}
137 | 
138 | 	// If player is in turn
139 | 	if engine.State == StatePlayerTurn {
140 | 		actions := engine.AvailableActions()
141 | 		if len(actions) == 0 {
142 | 			t.Errorf("Expected at least 1 action during player turn")
143 | 		}
144 | 		// Stand to conclude round
145 | 		err = engine.Step(ActionStand)
146 | 		if err != nil {
147 | 			t.Fatalf("Stand failed: %v", err)
148 | 		}
149 | 	}
150 | 
151 | 	if engine.State != StateRoundResolved {
152 | 		t.Fatalf("Expected round to be resolved, got %v", engine.State)
153 | 	}
154 | 
155 | 	_ = engine.NetRoundProfit()
156 | }
