109 | // Shoe represents a multi-deck dealing shoe.
110 | type Shoe struct {
111 | 	mu           sync.Mutex
112 | 	cards        []Card
113 | 	dealtCards   []Card
114 | 	totalDecks   int
115 | 	cutCardIndex int
116 | 	rng          *rand.Rand
117 | 	onDeal       func(Card)
118 | }
119 | 
120 | // ShoeOption defines functional options for Shoe creation.
121 | type ShoeOption func(*Shoe)
122 | 
123 | // WithCutCardPenetration sets the shoe cut card penetration percentage (e.g. 0.75 = 75%).
124 | func WithCutCardPenetration(penetration float64) ShoeOption {
125 | 	return func(s *Shoe) {
126 | 		if penetration <= 0 || penetration >= 1.0 {
127 | 			penetration = 0.75
128 | 		}
129 | 		total := s.totalDecks * 52
130 | 		s.cutCardIndex = int(float64(total) * penetration)
131 | 	}
132 | }
133 | 
134 | // WithCustomRNG sets a custom random generator (useful for reproducible tests).
135 | func WithCustomRNG(rng *rand.Rand) ShoeOption {
136 | 	return func(s *Shoe) {
137 | 		s.rng = rng
138 | 	}
139 | }
140 | 
141 | // WithDealListener registers a callback invoked every time a card is dealt.
142 | func WithDealListener(callback func(Card)) ShoeOption {
143 | 	return func(s *Shoe) {
144 | 		s.onDeal = callback
145 | 	}
146 | }
147 | 
148 | // NewShoe initializes and shuffles a multi-deck shoe (1 to 8 decks).
149 | func NewShoe(numDecks int, opts ...ShoeOption) *Shoe {
150 | 	if numDecks < 1 {
151 | 		numDecks = 1
152 | 	}
153 | 	if numDecks > 8 {
154 | 		numDecks = 8
155 | 	}
156 | 
157 | 	s := &Shoe{
158 | 		totalDecks: numDecks,
159 | 		rng:        rand.New(rand.NewSource(time.Now().UnixNano())),
160 | 	}
161 | 
162 | 	// Default cut card index: 75%
163 | 	s.cutCardIndex = int(float64(numDecks*52) * 0.75)
164 | 
165 | 	for _, opt := range opts {
166 | 		opt(s)
167 | 	}
168 | 
169 | 	s.ResetAndShuffle()
170 | 	return s
171 | }
172 | 
173 | // ResetAndShuffle refills the shoe with full decks and performs a Fisher-Yates shuffle.
174 | func (s *Shoe) ResetAndShuffle() {
175 | 	s.mu.Lock()
176 | 	defer s.mu.Unlock()
177 | 
178 | 	totalCards := s.totalDecks * 52
179 | 	s.cards = make([]Card, 0, totalCards)
180 | 	s.dealtCards = make([]Card, 0, totalCards)
181 | 
182 | 	allSuits := []Suit{Spades, Hearts, Diamonds, Clubs}
183 | 	allRanks := []Rank{Two, Three, Four, Five, Six, Seven, Eight, Nine, Ten, Jack, Queen, King, Ace}
184 | 
185 | 	for d := 0; d < s.totalDecks; d++ {
186 | 		for _, suit := range allSuits {
187 | 			for _, rank := range allRanks {
188 | 				s.cards = append(s.cards, Card{Rank: rank, Suit: suit})
189 | 			}
190 | 		}
191 | 	}
192 | 
193 | 	// Fisher-Yates shuffle
194 | 	for i := len(s.cards) - 1; i > 0; i-- {
195 | 		j := s.rng.Intn(i + 1)
196 | 		s.cards[i], s.cards[j] = s.cards[j], s.cards[i]
197 | 	}
198 | }
199 | 
200 | // Deal pops the top card from the shoe. If empty, it automatically resets & shuffles.
201 | func (s *Shoe) Deal() Card {
202 | 	s.mu.Lock()
203 | 	if len(s.cards) == 0 {
204 | 		s.mu.Unlock()
205 | 		s.ResetAndShuffle()
206 | 		s.mu.Lock()
207 | 	}
208 | 
209 | 	idx := len(s.cards) - 1
210 | 	card := s.cards[idx]
211 | 	s.cards = s.cards[:idx]
212 | 	s.dealtCards = append(s.dealtCards, card)
213 | 
214 | 	cb := s.onDeal
215 | 	s.mu.Unlock()
216 | 
217 | 	if cb != nil {
218 | 		cb(card)
219 | 	}
220 | 	return card
221 | }
