223 | // NeedsShuffle returns true if dealt cards count has passed the cut card index.
224 | func (s *Shoe) NeedsShuffle() bool {
225 | 	s.mu.Lock()
226 | 	defer s.mu.Unlock()
227 | 	return len(s.dealtCards) >= s.cutCardIndex
228 | }
