230 | // RemainingCards returns the number of un-dealt cards in the shoe.
231 | func (s *Shoe) RemainingCards() int {
232 | 	s.mu.Lock()
233 | 	defer s.mu.Unlock()
234 | 	return len(s.cards)
235 | }
236 | 
237 | // DealtCount returns the number of cards dealt so far.
238 | func (s *Shoe) DealtCount() int {
239 | 	s.mu.Lock()
240 | 	defer s.mu.Unlock()
241 | 	return len(s.dealtCards)
242 | }
