216 | 	// Check if split is allowed by rules
217 | 	if !g.Rules.DoubleAfterSplit && len(g.PlayerHands) >= 2 {
218 | 		// Can't split more than once if split after double not allowed
219 | 		return false
220 | 	}
221 | 
222 | 	// Create new hand with second card
223 | 	newHand := PlayerHand{
224 | 		Cards:      models.Hand{hand.Cards[1]},
225 | 		Bet:        hand.Bet,
226 | 		SplitCount: hand.SplitCount + 1,
227 | 	}
228 | 	g.PlayerHands = append(g.PlayerHands, newHand)
229 | 
230 | 	// Update current hand with first card
231 | 	hand.Cards = models.Hand{hand.Cards[0]}
