241 | func (g *Game) PlayerSurrender() bool {
242 | 	if g.State != StatePlayerTurn || g.CurrentHand >= len(g.PlayerHands) {
243 | 		return false
244 | 	}
245 | 
246 | 	hand := &g.PlayerHands[g.CurrentHand]
247 | 	hand.IsBusted = true
