253 | // PlayerTakeInsurance makes an insurance bet
254 | func (g *Game) PlayerTakeInsurance(bet float64) bool {
255 | 	if g.State != StatePlayerTurn || g.Insurance > 0 {
256 | 		return false
257 | 	}
258 | 
259 | 	// Can only take insurance if dealer shows ace
260 | 	if g.DealerHand.Cards[0].Rank != models.Ace {
261 | 		return false
262 | 	}
263 | 
264 | 	g.Insurance = bet
265 | 	return true
