268 | // EndPlayerTurn ends the player's turn and moves to dealer turn
269 | func (g *Game) EndPlayerTurn() {
270 | 	allStoodOrBusted := true
271 | 	for _, hand := range g.PlayerHands {
272 | 		if !hand.IsStood && !hand.IsBusted {
273 | 			allStoodOrBusted = false
274 | 			break
275 | 		}
276 | 	}
277 | 
278 | 	if allStoodOrBusted {
279 | 		g.State = StateDealerTurn
280 | 		g.dealerPlay()
281 | 		g.State = StateSettlement
282 | 	}
283 | }
