285 | // dealerPlay plays the dealer's hand according to rules
286 | func (g *Game) dealerPlay() {
287 | 	g.DealerHand.IsHidden = false
288 | 
289 | 	for {
290 | 		score, isSoft := g.DealerHand.Cards.Score()
291 | 
292 | 		// Dealer hits on soft 17 or less based on rules
293 | 		shouldHit := false
294 | 		if score < 17 {
295 | 			shouldHit = true
296 | 		} else if score == 17 && isSoft && g.Rules.DealerHitsSoft17 {
297 | 			shouldHit = true
298 | 		}
299 | 
300 | 		if !shouldHit {
301 | 			break
302 | 		}
303 | 
304 | 		g.DealerHand.Cards = append(g.DealerHand.Cards, g.Shoe.Deal())
305 | 
306 | 		if g.DealerHand.Cards.IsBusted() {
307 | 			g.DealerHand.IsBusted = true
308 | 			break
309 | 		}
310 | 	}
311 | }
