313 | // CalculateResults calculates the outcome for each player hand
314 | func (g *Game) CalculateResults() []GameResult {
315 | 	results := make([]GameResult, len(g.PlayerHands))
316 | 
317 | 	dealerScore, _ := g.DealerHand.Cards.Score()
318 | 
319 | 	for i, hand := range g.PlayerHands {
320 | 		result := GameResult{
321 | 			HandIndex: i,
322 | 			BetResult: rules.Push,
323 | 			Wager:     hand.Bet,
324 | 		}
325 | 
326 | 		if hand.IsBusted {
327 | 			result.BetResult = rules.Loss
328 | 			result.Payout = 0
329 | 		} else if hand.IsBlackjack {
330 | 			if g.DealerHand.Cards.IsBlackjack() {
331 | 				result.BetResult = rules.Push
332 | 				result.Payout = hand.Bet
333 | 			} else {
334 | 				result.BetResult = rules.Win
335 | 				result.Payout = hand.Bet * (1 + g.Rules.BlackjackPayout)
336 | 				result.IsBlackjack = true
337 | 			}
338 | 		} else if g.DealerHand.IsBusted {
339 | 			result.BetResult = rules.Win
340 | 			result.Payout = hand.Bet * 2
341 | 		} else {
342 | 			playerScore, _ := hand.Cards.Score()
343 | 			if playerScore > dealerScore {
344 | 				result.BetResult = rules.Win
345 | 				result.Payout = hand.Bet * 2
346 | 			} else if playerScore < dealerScore {
347 | 				result.BetResult = rules.Loss
348 | 				result.Payout = 0
349 | 			} else {
350 | 				result.BetResult = rules.Push
351 | 				result.Payout = hand.Bet
352 | 			}
353 | 		}
354 | 
355 | 		results[i] = result
356 | 	}
357 | 
358 | 	return results
359 | }
360 | 
361 | // CalculateInsuranceResult calculates insurance payout
362 | func (g *Game) CalculateInsuranceResult() rules.BetResult {
363 | 	if g.Insurance == 0 {
364 | 		return rules.InsuranceLoss
365 | 	}
366 | 
367 | 	if g.DealerHand.Cards.IsBlackjack() {
368 | 		// Insurance pays 2:1
369 | 		return rules.InsuranceWin
370 | 	}
371 | 	return rules.InsuranceLoss
372 | }
