 33 | // Value calculates the best possible value of a hand (with aces as 1 or 11)
 34 | func (h *Hand) Value() int {
 35 | 	value := 0
 36 | 	aces := 0
 37 | 
 38 | 	for _, card := range h.Cards {
 39 | 		if card.Rank == cards.Ace {
 40 | 			aces++
 41 | 			value += 11
 42 | 		} else {
 43 | 			value += card.Value
 44 | 		}
 45 | 	}
 46 | 
 47 | 	// Adjust for aces if value exceeds 21
 48 | 	for aces > 0 && value > 21 {
 49 | 		value -= 10 // Change ace from 11 to 1
 50 | 		aces--
 51 | 	}
 52 | 
 53 | 	return value
 54 | }
