 56 | // IsSoft returns true if the hand contains an ace counted as 11
 57 | func (h *Hand) IsSoft() bool {
 58 | 	valueWithoutAceAdjustment := 0
 59 | 	hasAce := false
 60 | 
 61 | 	for _, card := range h.Cards {
 62 | 		if card.Rank == cards.Ace {
 63 | 			hasAce = true
 64 | 			valueWithoutAceAdjustment += 11
 65 | 		} else {
 66 | 			valueWithoutAceAdjustment += card.Value
 67 | 		}
 68 | 	}
 69 | 
 70 | 	// If the value without adjustment is <= 21 and has an ace, it's soft
 71 | 	originalValue := valueWithoutAceAdjustment
 72 | 	acesCount := 0
 73 | 	for _, card := range h.Cards {
 74 | 		if card.Rank == cards.Ace {
 75 | 			acesCount++
 76 | 		}
 77 | 	}
 78 | 
 79 | 	// Check if after ace adjustments it's still soft
 80 | 	valueWithAceAdjustment := h.Value()
 81 | 
 82 | 	// If original value <= 21 and we had to adjust aces, it's soft
 83 | 	// Or if the value is less than original due to ace adjustments
 84 | 	return hasAce && valueWithAceAdjustment <= 21 && valueWithAceAdjustment != originalValue
 85 | }
