 87 | // CanSplit returns true if the hand can be split (same rank cards, not already split beyond max)
 88 | func (h *Hand) CanSplit(rules *RuleSet) bool {
 89 | 	if len(h.Cards) != 2 {
 90 | 		return false
 91 | 	}
 92 | 
 93 | 	// Cards must be of the same rank (or both worth 10 for face cards)
 94 | 	card1, card2 := h.Cards[0], h.Cards[1]
 95 | 
 96 | 	// If both are aces, special handling
 97 | 	if card1.Rank == cards.Ace && card2.Rank == cards.Ace {
 98 | 		if rules.SplitAcesOnceOnly {
 99 | 			return true // Can split aces once regardless of other rules
100 | 		}
101 | 		return !rules.SplitAcesOnceOnly // If not limited to one split, allow more
102 | 	}
103 | 
104 | 	// Same rank (A-A, K-K, etc.) or both 10-value cards (K-Q, J-10, etc.)
105 | 	return card1.Rank == card2.Rank || (card1.Value == card2.Value && card1.Value == 10)
106 | }
