186 | func (g *GameEngine) DealInitialCards() error {
187 | 	if g.State != BettingState {
188 | 		return errors.New("cannot deal cards when not in betting state")
189 | 	}
190 | 
191 | 	// Verify all players have placed bets
192 | 	for _, player := range g.Players {
193 | 		if player.CurrentBet <= 0 {
194 | 			return errors.New("all players must place bets before dealing")
195 | 		}
196 | 	}
197 | 
198 | 	// Deal two cards to each player and the dealer
199 | 	for i := 0; i < 2; i++ {
200 | 		for _, player := range g.Players {
201 | 			card, err := g.Shoe.DrawCard()
202 | 			if err != nil {
203 | 				return err
204 | 			}
205 | 
206 | 			// Create the initial hand for the player
207 | 			if len(player.Hands) == 0 {
208 | 				hand := &Hand{
209 | 					Cards:  []cards.Card{card},
210 | 					Bet:    player.CurrentBet,
211 | 					Active: true,
212 | 				}
213 | 				player.Hands = append(player.Hands, hand)
214 | 			} else {
215 | 				player.Hands[0].Cards = append(player.Hands[0].Cards, card)
216 | 			}
217 | 		}
218 | 
219 | 		// Deal to dealer
220 | 		card, err := g.Shoe.DrawCard()
221 | 		if err != nil {
222 | 			return err
223 | 		}
224 | 		g.Dealer.Cards = append(g.Dealer.Cards, card)
225 | 	}
226 | 
227 | 	// Check for blackjacks
228 | 	g.checkForBlackjacks()
229 | 
230 | 	// Transition to next state
231 | 	if g.anyActivePlayers() {
232 | 		g.State = PlayerTurnState
233 | 		g.CurrentPlayerIndex = 0
