257 | // hasBlackjack checks if a hand has a blackjack (ace + 10-value card)
258 | func (g *GameEngine) hasBlackjack(hand *Hand) bool {
259 | 	if len(hand.Cards) != 2 {
260 | 		return false
261 | 	}
262 | 
263 | 	card1, card2 := hand.Cards[0], hand.Cards[1]
264 | 
265 | 	// Check if one card is an ace and the other is a 10-value card
266 | 	isAceFirst := card1.Rank == cards.Ace
267 | 	isAceSecond := card2.Rank == cards.Ace
268 | 	isTenValuedFirst := card1.Value == 10
269 | 	isTenValuedSecond := card2.Value == 10
270 | 
271 | 	return (isAceFirst && isTenValuedSecond) || (isAceSecond && isTenValuedFirst)
272 | }
