391 | // Split splits the current hand into two hands
392 | func (g *GameEngine) Split(playerID int) error {
393 | 	if g.State != PlayerTurnState {
394 | 		return errors.New("cannot split when not in player turn state")
395 | 	}
396 | 
397 | 	player := g.getPlayerByID(playerID)
398 | 	if player == nil {
399 | 		return errors.New("player not found")
400 | 	}
401 | 
402 | 	currentHand := g.getCurrentHand(player)
403 | 	if currentHand == nil {
404 | 		return errors.New("no active hand found")
405 | 	}
406 | 
407 | 	if !currentHand.CanSplit(g.Rules) {
408 | 		return errors.New("cannot split this hand")
409 | 	}
410 | 
411 | 	// Check if player has enough chips to split
412 | 	if player.Chips < currentHand.Bet {
413 | 		return errors.New("insufficient chips to split")
414 | 	}
415 | 
416 | 	// Deduct the additional bet amount
417 | 	player.Chips -= currentHand.Bet
418 | 
419 | 	// Split the hand
420 | 	cardToSplit := currentHand.Cards[1]
421 | 	currentHand.Cards = currentHand.Cards[:1] // Remove the second card
422 | 
423 | 	newHand := &Hand{
424 | 		Cards:   []cards.Card{cardToSplit},
425 | 		Bet:     currentHand.Bet,
426 | 		Active:  true,
427 | 		IsSplit: true,
428 | 	}
429 | 
430 | 	player.Hands = append(player.Hands, newHand)
431 | 
432 | 	// Draw a card for each hand
433 | 	card1, err := g.Shoe.DrawCard()
434 | 	if err != nil {
435 | 		return err
436 | 	}
437 | 	currentHand.Cards = append(currentHand.Cards, card1)
438 | 
439 | 	card2, err := g.Shoe.DrawCard()
440 | 	if err != nil {
441 | 		return err
442 | 	}
443 | 	newHand.Cards = append(newHand.Cards, card2)
444 | 
445 | 	// Check for blackjacks after split
446 | 	if g.hasBlackjack(currentHand) {
447 | 		currentHand.IsBlackjack = true
448 | 		currentHand.Active = false
449 | 	}
450 | 	if g.hasBlackjack(newHand) {
451 | 		newHand.IsBlackjack = true
452 | 		newHand.Active = false
453 | 	}
454 | 
455 | 	// If splitting aces, both hands get one card only
456 | 	if currentHand.Cards[0].Rank == cards.Ace && g.Rules.SplitAcesOnceOnly {
457 | 		currentHand.Active = false
458 | 		newHand.Active = false
459 | 	}
460 | 
461 | 	// Move to the next hand
462 | 	g.CurrentHandIndex++
463 | 
464 | 	return nil
465 | }
