554 | // ResolveRound resolves all player hands against the dealer
555 | func (g *GameEngine) ResolveRound() error {
556 | 	if g.State != EndRoundState {
557 | 		return errors.New("round not ready to be resolved")
558 | 	}
559 | 
560 | 	for _, player := range g.Players {
561 | 		for _, hand := range player.Hands {
562 | 			result := g.calculateHandResult(hand)
563 | 
564 | 			switch result {
565 | 			case "win":
566 | 				player.Chips += hand.Bet * 2 // Original bet back plus winnings (equal to bet amount)
567 | 			case "lose":
568 | 				// Player loses their bet (already deducted in PlaceBet)
569 | 			case "push":
570 | 				player.Chips += hand.Bet // Return original bet
571 | 			case "blackjack":
572 | 				payout := math.Round(hand.Bet*g.Rules.BlackjackPayout*100) / 100 // Round to 2 decimal places
573 | 				player.Chips += hand.Bet + payout                                // Original bet back plus payout
574 | 			}
575 | 		}
576 | 
577 | 		// Reset player hands for next round
578 | 		player.Hands = make([]*Hand, 0)
579 | 		player.CurrentBet = 0
580 | 	}
581 | 
582 | 	// Reset dealer hand
583 | 	g.Dealer = &Hand{Cards: make([]cards.Card, 0)}
584 | 
585 | 	g.State = BettingState
586 | 
587 | 	return nil
588 | }
