640 | // moveToNextPlayer moves to the next player with active hands
641 | func (g *GameEngine) moveToNextPlayer() {
642 | 	// Find next player with active hands
643 | 	for i := g.CurrentPlayerIndex + 1; i < len(g.Players); i++ {
644 | 		player := g.Players[i]
645 | 		for _, hand := range player.Hands {
646 | 			if hand.Active {
647 | 				g.CurrentPlayerIndex = i
648 | 				g.CurrentHandIndex = 0
649 | 				// Find the first active hand for this player
650 | 				for j, h := range player.Hands {
651 | 					if h.Active {
652 | 						g.CurrentHandIndex = j
653 | 						return
654 | 					}
655 | 				}
656 | 				break
657 | 			}
658 | 		}
659 | 	}
660 | 
661 | 	// If no more players with active hands, move to dealer turn
662 | 	if !g.anyActivePlayers() {
663 | 		g.StartDealerTurn()
664 | 	}
665 | }
