159 | 	// Check for blackjacks
160 | 	playerHasBlackjack := s.isBlackjackHand(playerHand)
161 | 	dealerHasBlackjack := s.isBlackjackHand(dealerHand)
162 | 
163 | 	if playerHasBlackjack || dealerHasBlackjack {
164 | 		// If both have blackjack, it's a push
165 | 		// If only player has blackjack, player wins
166 | 		// If only dealer has blackjack, dealer wins
167 | 		if playerHasBlackjack && dealerHasBlackjack {
168 | 			// Push - return the hand to indicate the result
169 | 		} else if playerHasBlackjack {
170 | 			playerHand.IsBlackjack = true
171 | 		}
172 | 		// In a real simulation, we'd return the result here
173 | 		return playerHand
174 | 	}
175 | 
176 | 	// Initialize card counter if needed
177 | 	var counter *oracle.CardCounter
178 | 	var advisor *oracle.StrategyAdvisor
179 | 
180 | 	if s.UseCardCounting {
181 | 		counter = oracle.NewCardCounter(s.CountSystem, s.RuleSet.NumDecks)
182 | 		advisor = oracle.NewStrategyAdvisor(s.RuleSet, counter)
183 | 
184 | 		// Count the initial cards dealt
