220 | func (s *Simulator) playPlayerTurn(playerHand *game.Hand, dealerUpcard cards.Card, shoe *cards.Shoe, advisor *oracle.StrategyAdvisor, counter *oracle.CardCounter) *game.Hand {
221 | 	// Continue player's turn until they stand or bust
222 | 	for playerHand.Active && s.getHandValue(playerHand.Cards) <= 21 && !playerHand.IsBusted && !playerHand.IsBlackjack {
223 | 		var action oracle.Action
224 | 		if advisor != nil {
225 | 			if s.UseCardCounting {
226 | 				action = advisor.GetAdvancedAction(playerHand.Cards, dealerUpcard, playerHand.Bet)
227 | 			} else {
228 | 				action = advisor.GetRecommendedAction(playerHand.Cards, dealerUpcard, playerHand.Bet)
229 | 			}
230 | 		} else {
231 | 			// Fallback to basic strategy
232 | 			action = s.getBasicStrategyAction(playerHand.Cards, dealerUpcard)
233 | 		}
234 | 
235 | 		switch action {
236 | 		case oracle.HitAction:
237 | 			card, err := shoe.DrawCard()
238 | 			if err != nil {
239 | 				break // No more cards
240 | 			}
241 | 			playerHand.Cards = append(playerHand.Cards, card)
242 | 
243 | 			// Update counter if applicable
244 | 			if counter != nil {
245 | 				counter.UpdateCount(card)
246 | 			}
247 | 
248 | 			// Check if the hand busted
249 | 			if s.getHandValue(playerHand.Cards) > 21 {
250 | 				playerHand.IsBusted = true
251 | 				playerHand.Active = false
252 | 			}
253 | 		case oracle.StandAction:
254 | 			playerHand.Active = false
255 | 		case oracle.DoubleAction:
256 | 			// For simulation, just take one more card and stop
257 | 			card, err := shoe.DrawCard()
258 | 			if err != nil {
259 | 				break // No more cards
260 | 			}
261 | 			playerHand.Cards = append(playerHand.Cards, card)
262 | 
263 | 			// Update counter if applicable
264 | 			if counter != nil {
265 | 				counter.UpdateCount(card)
266 | 			}
267 | 
268 | 			if s.getHandValue(playerHand.Cards) > 21 {
269 | 				playerHand.IsBusted = true
270 | 			}
271 | 			playerHand.Active = false
272 | 		case oracle.SplitAction:
273 | 			// For simulation purposes, we'll just continue with the current hand
274 | 			playerHand.Active = false
275 | 		default:
276 | 			// Default to hit
277 | 			card, err := shoe.DrawCard()
278 | 			if err != nil {
279 | 				break // No more cards
280 | 			}
281 | 			playerHand.Cards = append(playerHand.Cards, card)
282 | 
283 | 			// Update counter if applicable
284 | 			if counter != nil {
285 | 				counter.UpdateCount(card)
286 | 			}
287 | 
288 | 			if s.getHandValue(playerHand.Cards) > 21 {
289 | 				playerHand.IsBusted = true
290 | 				playerHand.Active = false
291 | 			}
292 | 		}
293 | 	}
294 | 
295 | 	return playerHand
