298 | // playRandomPlayerTurn simulates the player's turn with random actions
299 | func (s *Simulator) playRandomPlayerTurn(playerHand *game.Hand, dealerUpcard cards.Card, shoe *cards.Shoe) *game.Hand {
300 | 	// Continue player's turn until they stand or bust
301 | 	for playerHand.Active && s.getHandValue(playerHand.Cards) <= 21 && !playerHand.IsBusted {
302 | 		// Randomly select an action
303 | 		actions := []oracle.Action{oracle.HitAction, oracle.StandAction, oracle.DoubleAction}
304 | 		randomAction := actions[rand.Intn(len(actions))]
305 | 
306 | 		switch randomAction {
307 | 		case oracle.HitAction:
308 | 			card, err := shoe.DrawCard()
309 | 			if err != nil {
310 | 				break // No more cards
311 | 			}
312 | 			playerHand.Cards = append(playerHand.Cards, card)
313 | 
314 | 			// Check if the hand busted
315 | 			if s.getHandValue(playerHand.Cards) > 21 {
316 | 				playerHand.IsBusted = true
317 | 				playerHand.Active = false
318 | 			}
319 | 		case oracle.StandAction:
320 | 			playerHand.Active = false
321 | 		case oracle.DoubleAction:
322 | 			// For simulation, just take one more card and stop
323 | 			card, err := shoe.DrawCard()
324 | 			if err != nil {
325 | 				break // No more cards
326 | 			}
327 | 			playerHand.Cards = append(playerHand.Cards, card)
328 | 
329 | 			if s.getHandValue(playerHand.Cards) > 21 {
330 | 				playerHand.IsBusted = true
331 | 			}
332 | 			playerHand.Active = false
333 | 		}
334 | 	}
335 | 
336 | 	return playerHand
337 | }
