339 | // playDealerTurn simulates the dealer's turn according to fixed rules
340 | func (s *Simulator) playDealerTurn(dealerHand *game.Hand, shoe *cards.Shoe, ruleSet *game.RuleSet) *game.Hand {
341 | 	for {
342 | 		dealerValue := s.getHandValue(dealerHand.Cards)
343 | 
344 | 		// Dealer hits on soft 17 if configured, otherwise stands on hard 17+
345 | 		if dealerValue < 17 || (dealerValue == 17 && ruleSet.DealerHitsSoft17 && s.isSoftHand(dealerHand.Cards)) {
346 | 			card, err := shoe.DrawCard()
347 | 			if err != nil {
348 | 				break // No more cards
349 | 			}
350 | 			dealerHand.Cards = append(dealerHand.Cards, card)
351 | 
352 | 			if s.getHandValue(dealerHand.Cards) > 21 {
353 | 				dealerHand.IsBusted = true
354 | 				break
355 | 			}
356 | 		} else {
357 | 			break // Dealer stands
358 | 		}
359 | 	}
360 | 
361 | 	return dealerHand
362 | }
