364 | // getBasicStrategyAction returns the basic strategy action for a given hand
365 | func (s *Simulator) getBasicStrategyAction(hand []cards.Card, dealerUpcard cards.Card) oracle.Action {
366 | 	playerSum := s.getHandValue(hand)
367 | 	dealerValue := s.getCardValue(dealerUpcard)
368 | 
369 | 	// Check for pairs first
370 | 	if len(hand) == 2 && hand[0].Rank == hand[1].Rank {
371 | 		switch hand[0].Rank {
372 | 		case cards.Ace:
373 | 			return oracle.SplitAction
374 | 		case cards.Eight:
375 | 			return oracle.SplitAction
376 | 		case cards.Nine:
377 | 			if dealerValue == 7 || dealerValue >= 10 {
378 | 				return oracle.StandAction
379 | 			} else if dealerValue >= 2 && dealerValue <= 6 || dealerValue == 8 || dealerValue == 9 {
380 | 				return oracle.SplitAction
381 | 			}
382 | 		case cards.Six:
383 | 			if dealerValue >= 2 && dealerValue <= 6 {
384 | 				return oracle.SplitAction
385 | 			}
386 | 		case cards.Five:
387 | 			if dealerValue >= 2 && dealerValue <= 9 {
388 | 				return oracle.DoubleAction
389 | 			}
390 | 		case cards.Four:
391 | 			if dealerValue >= 5 && dealerValue <= 6 && s.RuleSet.DoubleAfterSplit {
392 | 				return oracle.SplitAction
393 | 			}
394 | 		case cards.Three, cards.Two:
395 | 			if dealerValue >= 2 && dealerValue <= 7 {
396 | 				return oracle.SplitAction
397 | 			}
398 | 		}
399 | 	}
400 | 
401 | 	// Check for soft hands (hands with an ace counted as 11)
402 | 	if s.isSoftHand(hand) {
403 | 		switch playerSum {
404 | 		case 20: // A-9
405 | 			return oracle.StandAction
406 | 		case 19: // A-8
407 | 			if dealerValue == 6 {
408 | 				return oracle.DoubleAction
409 | 			}
410 | 			return oracle.StandAction
411 | 		case 18: // A-7
412 | 			if dealerValue >= 3 && dealerValue <= 6 {
413 | 				return oracle.DoubleAction
414 | 			} else if dealerValue == 2 || dealerValue == 7 || dealerValue == 8 {
415 | 				return oracle.StandAction
416 | 			}
417 | 			return oracle.HitAction
418 | 		case 17: // A-6
419 | 			if dealerValue >= 3 && dealerValue <= 6 {
420 | 				return oracle.DoubleAction
421 | 			}
422 | 			return oracle.HitAction
423 | 		case 16, 15: // A-5, A-4
424 | 			if dealerValue >= 4 && dealerValue <= 6 {
425 | 				return oracle.DoubleAction
426 | 			}
427 | 			return oracle.HitAction
428 | 		case 14, 13: // A-3, A-2
429 | 			if dealerValue == 5 || dealerValue == 6 {
430 | 				return oracle.DoubleAction
431 | 			}
432 | 			return oracle.HitAction
433 | 		}
434 | 		return oracle.HitAction
435 | 	}
436 | 
437 | 	// Hard hands
438 | 	switch playerSum {
439 | 	case 20, 19, 18, 17:
440 | 		return oracle.StandAction
441 | 	case 16:
442 | 		if dealerValue >= 2 && dealerValue <= 6 {
443 | 			return oracle.StandAction
444 | 		}
445 | 		return oracle.HitAction
446 | 	case 15:
447 | 		if dealerValue >= 2 && dealerValue <= 6 {
448 | 			return oracle.StandAction
449 | 		}
450 | 		return oracle.HitAction
451 | 	case 14, 13:
452 | 		if dealerValue >= 2 && dealerValue <= 6 {
453 | 			return oracle.StandAction
454 | 		}
455 | 		return oracle.HitAction
456 | 	case 12:
457 | 		if dealerValue >= 4 && dealerValue <= 6 {
458 | 			return oracle.StandAction
459 | 		}
460 | 		return oracle.HitAction
461 | 	case 11:
462 | 		return oracle.DoubleAction
463 | 	case 10:
464 | 		if dealerValue >= 2 && dealerValue <= 9 {
465 | 			return oracle.DoubleAction
466 | 		}
467 | 		return oracle.HitAction
468 | 	case 9:
469 | 		if dealerValue >= 3 && dealerValue <= 6 {
470 | 			return oracle.DoubleAction
471 | 		}
472 | 		return oracle.HitAction
473 | 	}
474 | 
475 | 	// Default to hit for low hands or if no other condition is met
476 | 	return oracle.HitAction
477 | }
