479 | // getHandValue calculates the value of a hand, preferring the highest value <= 21
480 | func (s *Simulator) getHandValue(hand []cards.Card) int {
481 | 	value := 0
482 | 	aces := 0
483 | 
484 | 	for _, card := range hand {
485 | 		if card.Rank == cards.Ace {
486 | 			aces++
487 | 			value += 11
488 | 		} else {
489 | 			value += s.getCardValue(card)
490 | 		}
491 | 	}
492 | 
493 | 	// Adjust for aces if value exceeds 21
494 | 	for aces > 0 && value > 21 {
495 | 		value -= 10 // Change ace from 11 to 1
496 | 		aces--
497 | 	}
498 | 
499 | 	return value
500 | }
