507 | // isSoftHand returns true if the hand contains an ace counted as 11
508 | func (s *Simulator) isSoftHand(hand []cards.Card) bool {
509 | 	valueWithoutAceAdjustment := 0
510 | 	hasAce := false
511 | 
512 | 	for _, card := range hand {
513 | 		if card.Rank == cards.Ace {
514 | 			hasAce = true
515 | 			valueWithoutAceAdjustment += 11
516 | 		} else {
517 | 			valueWithoutAceAdjustment += s.getCardValue(card)
518 | 		}
519 | 	}
520 | 
521 | 	// If the value without adjustment is <= 21 and has an ace, it's soft
522 | 	originalValue := valueWithoutAceAdjustment
523 | 	acesCount := 0
524 | 	for _, card := range hand {
525 | 		if card.Rank == cards.Ace {
526 | 			acesCount++
527 | 		}
528 | 	}
529 | 
530 | 	// Check if after ace adjustments it's still soft
531 | 	valueWithAceAdjustment := s.getHandValue(hand)
532 | 
533 | 	// If original value <= 21 and we had to adjust aces, it's soft
534 | 	// Or if the value is less than original due to ace adjustments
535 | 	return hasAce && valueWithAceAdjustment <= 21 && valueWithAceAdjustment != originalValue
536 | }
