116 | // checkPairStrategy returns the recommended action for a pair
117 | func (sa *StrategyAdvisor) checkPairStrategy(rank cards.Rank, dealerValue int, isSoft bool) Action {
118 | 	// Convert dealer value to proper representation (11 for Ace)
119 | 	if dealerValue == 11 && rank == cards.Ace {
120 | 		// Special case for pair of aces
121 | 		return SplitAction
122 | 	}
123 | 
124 | 	// Basic pair strategy based on rank and dealer upcard
125 | 	switch rank {
126 | 	case cards.Ace:
127 | 		return SplitAction // Always split aces
128 | 	case cards.Eight:
129 | 		return SplitAction // Always split eights
130 | 	case cards.Ten:
131 | 		return StandAction // Never split tens
132 | 	case cards.Nine:
133 | 		// Split 9-9 against dealer 2-6, 8-9; Stand against 7, 10, A
134 | 		if dealerValue >= 2 && dealerValue <= 6 || dealerValue == 8 || dealerValue == 9 {
135 | 			return SplitAction
136 | 		} else if dealerValue == 7 || dealerValue == 10 || dealerValue == 11 {
137 | 			return StandAction
138 | 		}
139 | 	case cards.Seven:
140 | 		// Split 7-7 against dealer 2-7; Hit against 8-A
141 | 		if dealerValue >= 2 && dealerValue <= 7 {
142 | 			return SplitAction
143 | 		} else {
144 | 			return HitAction
145 | 		}
146 | 	case cards.Six:
147 | 		// Split 6-6 against dealer 2-6; Hit against 7-A
148 | 		if dealerValue >= 2 && dealerValue <= 6 {
149 | 			return SplitAction
150 | 		} else {
151 | 			return HitAction
152 | 		}
153 | 	case cards.Five:
154 | 		// Treat as hard 10
155 | 		return sa.getHardHandStrategy(10, dealerValue)
156 | 	case cards.Four:
157 | 		// Split 4-4 against dealer 5-6 only (if DAS allowed)
158 | 		if sa.RuleSet.DoubleAfterSplit && dealerValue == 5 || dealerValue == 6 {
159 | 			return SplitAction
160 | 		} else {
161 | 			return HitAction
162 | 		}
163 | 	case cards.Three, cards.Two:
164 | 		// Split 2-2, 3-3 against dealer 2-7; Hit against 8-A
165 | 		if dealerValue >= 2 && dealerValue <= 7 {
166 | 			return SplitAction
167 | 		} else {
168 | 			return HitAction
169 | 		}
170 | 	}
171 | 
172 | 	// Default: don't split
173 | 	return ""
174 | }
