176 | // getSoftHandStrategy returns the recommended action for a soft hand
177 | func (sa *StrategyAdvisor) getSoftHandStrategy(playerSum int, dealerValue int) Action {
178 | 	// Basic soft hand strategy
179 | 	switch playerSum {
180 | 	case 20: // A-9
181 | 		return StandAction
182 | 	case 19: // A-8
183 | 		// Stand, except double against dealer 6 (if allowed and only first 2 cards)
184 | 		if dealerValue == 6 {
185 | 			return DoubleAction
186 | 		}
187 | 		return StandAction
188 | 	case 18: // A-7
189 | 		if dealerValue == 2 || dealerValue == 7 || dealerValue == 8 {
190 | 			return StandAction
191 | 		} else if dealerValue >= 3 && dealerValue <= 6 {
192 | 			// Double if allowed, otherwise stand
193 | 			return DoubleAction
194 | 		} else {
195 | 			return HitAction
196 | 		}
197 | 	case 17: // A-6
198 | 		if dealerValue >= 3 && dealerValue <= 6 {
199 | 			// Double if allowed, otherwise hit
200 | 			return DoubleAction
201 | 		} else {
202 | 			return HitAction
203 | 		}
204 | 	case 16, 15: // A-5, A-4
205 | 		if dealerValue >= 4 && dealerValue <= 6 {
206 | 			// Double if allowed, otherwise hit
207 | 			return DoubleAction
208 | 		} else {
209 | 			return HitAction
210 | 		}
211 | 	case 14, 13: // A-3, A-2
212 | 		if dealerValue == 5 || dealerValue == 6 {
213 | 			// Double if allowed, otherwise hit
214 | 			return DoubleAction
215 | 		} else {
216 | 			return HitAction
217 | 		}
218 | 	default:
219 | 		return HitAction
220 | 	}
221 | }
