224 | func (sa *StrategyAdvisor) getHardHandStrategy(playerSum int, dealerValue int) Action {
225 | 	// Basic hard hand strategy
226 | 	if playerSum >= 17 {
227 | 		return StandAction
228 | 	} else if playerSum >= 13 {
229 | 		if dealerValue >= 2 && dealerValue <= 6 {
230 | 			return StandAction
231 | 		} else {
232 | 			return HitAction
233 | 		}
234 | 	} else if playerSum == 12 {
235 | 		if dealerValue >= 4 && dealerValue <= 6 {
236 | 			return StandAction
237 | 		} else {
238 | 			return HitAction
