240 | 	} else if playerSum == 11 {
241 | 		// Always double if allowed, otherwise hit
242 | 		return DoubleAction
243 | 	} else if playerSum == 10 {
244 | 		if dealerValue >= 2 && dealerValue <= 9 {
245 | 			// Double if allowed, otherwise hit
246 | 			return DoubleAction
247 | 		} else {
248 | 			return HitAction
249 | 		}
250 | 	} else if playerSum == 9 {
