263 | // GetAdvancedAction returns the optimal action with card counting adjustments
264 | func (sa *StrategyAdvisor) GetAdvancedAction(playerHand []cards.Card, dealerUpcard cards.Card, currentBet float64) Action {
265 | 	// Get the basic strategy action first
266 | 	basicAction := sa.GetRecommendedAction(playerHand, dealerUpcard, currentBet)
267 | 
268 | 	// Apply card counting adjustments
269 | 	trueCount := sa.Counter.TrueCount()
270 | 
271 | 	// Adjust based on true count deviations from basic strategy
272 | 	playerSum := sa.getHandValue(playerHand)
273 | 	dealerValue := sa.getCardValue(dealerUpcard)
274 | 
275 | 	// Specific index plays based on true count
276 | 	switch {
277 | 	case playerSum == 16 && dealerValue == 10:
278 | 		// 16 vs 10: Stand at TC >= 0, Hit at TC < 0
279 | 		if trueCount >= 0 && basicAction == HitAction {
280 | 			return StandAction
281 | 		}
282 | 	case playerSum == 15 && dealerValue == 10:
283 | 		// 15 vs 10: Stand at TC >= 4, Hit at TC < 4
284 | 		if trueCount >= 4 && basicAction == HitAction {
285 | 			return StandAction
286 | 		}
287 | 	case playerSum == 10 && dealerValue == 10:
288 | 		// 10 vs 10: Double at TC >= 4, otherwise hit
289 | 		if trueCount >= 4 && basicAction != DoubleAction {
290 | 			return DoubleAction
291 | 		}
292 | 	case playerSum == 12 && dealerValue >= 4 && dealerValue <= 6:
293 | 		// 12 vs 4,5,6: Stand at higher TC
294 | 		if (dealerValue == 4 && trueCount >= 5) ||
295 | 			(dealerValue == 5 && trueCount >= 3) ||
296 | 			(dealerValue == 6 && trueCount >= 2) {
297 | 			return StandAction
298 | 		}
299 | 	case playerSum == 13 && dealerValue == 2:
300 | 		// 13 vs 2: Stand at TC <= -2
301 | 		if trueCount <= -2 && basicAction == StandAction {
302 | 			return HitAction
303 | 		}
304 | 	case playerSum == 13 && dealerValue == 3:
305 | 		// 13 vs 3: Stand at TC <= -1
306 | 		if trueCount <= -1 && basicAction == StandAction {
307 | 			return HitAction
308 | 		}
309 | 	}
310 | 
311 | 	// For pair splitting adjustments
312 | 	if len(playerHand) == 2 && playerHand[0].Rank == playerHand[1].Rank {
313 | 		rank := playerHand[0].Rank
314 | 		switch {
315 | 		case rank == cards.Nine && dealerValue == 7:
316 | 			// 9-9 vs 7: Stand at TC >= 4, Split otherwise
317 | 			if trueCount >= 4 {
318 | 				return StandAction
319 | 			}
320 | 		case rank == cards.Ten && dealerValue == 5: // 10-10
321 | 			// 10-10 vs 5: Double at TC >= 5 (if allowed)
322 | 			if trueCount >= 5 && sa.RuleSet.DoubleAfterSplit {
323 | 				return DoubleAction
324 | 			}
325 | 		case rank == cards.Eight && dealerValue == 6:
326 | 			// 8-8 vs 6: Stand at very high TC (rare)
327 | 		}
328 | 	}
329 | 
330 | 	return basicAction
331 | }
