333 | // ShouldTakeInsurance returns whether the player should take insurance
334 | func (sa *StrategyAdvisor) ShouldTakeInsurance(dealerUpcard cards.Card, currentBet float64) bool {
335 | 	if dealerUpcard.Rank != cards.Ace {
336 | 		return false // Insurance only available when dealer shows Ace
337 | 	}
338 | 
339 | 	// In a neutral or negative count, insurance is generally not favorable
340 | 	// In a positive count rich in 10s, insurance becomes more favorable
