  7 | // Board represents an N x N chess board for the N-Queens problem.
  8 | // It stores the positions of placed queens and provides helper methods
  9 | // for validating placements against attack constraints.
 10 | type Board struct {
 11 | 	Size   int     // N for an N x N board
 12 | 	Queens []Queen // Slice of placed Queens, indexed by row.
 13 | }
 14 | 
 15 | // Solution represents a valid, complete solution to the N-Queens problem.
 16 | // It contains the positions of all N queens placed on the board without conflict.
 17 | type Solution struct {
 18 | 	Queens []Queen
 19 | }
 20 | 
 21 | // IsValid checks if a given solution is valid by ensuring no two queens threaten each other.
 22 | // This is useful for verifying the output of our solvers.
 23 | func (s Solution) IsValid() bool {
 24 | 	n := len(s.Queens)
 25 | 	for i := 0; i < n; i++ {
 26 | 		for j := i + 1; j < n; j++ {
 27 | 			q1 := s.Queens[i]
 28 | 			q2 := s.Queens[j]
 29 | 
 30 | 			// Check for same row
 31 | 			if q1.Row == q2.Row {
 32 | 				return false
 33 | 			}
 34 | 			// Check for same column
 35 | 			if q1.Col == q2.Col {
 36 | 				return false
 37 | 			}
 38 | 			// Check for same diagonal (both directions)
 39 | 			// Two queens are on the same diagonal if the absolute difference in rows
 40 | 			// equals the absolute difference in columns.
 41 | 			if abs(q1.Row-q2.Row) == abs(q1.Col-q2.Col) {
 42 | 				return false
 43 | 			}
 44 | 		}
 45 | 	}
 46 | 	return true
 47 | }
 48 | 
 49 | // Queen represents a queen piece on the board.
 50 | type Queen struct {
 51 | 	Row int // Zero-indexed row (0 to N-1)
 52 | 	Col int // Zero-indexed column (0 to N-1)
 53 | }
 54 | 
 55 | // NewBoard creates a new, empty N x N board.
 56 | func NewBoard(size int) *Board {
 57 | 	if size <= 0 {
 58 | 		return nil // Or handle error appropriately
 59 | 	}
 60 | 	return &Board{
 61 | 		Size:   size,
 62 | 		Queens: make([]Queen, 0, size),
 63 | 	}
 64 | }
 65 | 
 66 | // Place attempts to place a queen at the specified (row, col).
 67 | // It checks for conflicts with existing queens before placing.
 68 | // Returns an error if placement is invalid.
 69 | func (b *Board) Place(row, col int) error {
 70 | 	if !b.isValidPosition(row, col) {
 71 | 		return errors.New("invalid position: conflict detected")
 72 | 	}
 73 | 	b.Queens = append(b.Queens, Queen{Row: row, Col: col})
 74 | 	return nil
 75 | }
 76 | 
 77 | // isValidPosition checks if a queen can be safely placed at (row, col)
 78 | // by verifying it doesn't conflict with any existing queens on the board.
 79 | func (b *Board) isValidPosition(row, col int) bool {
 80 | 	for _, q := range b.Queens {
 81 | 		// Check for same row, same column, or same diagonal.
 82 | 		// Same row check is redundant if we place one queen per row.
 83 | 		if q.Row == row || q.Col == col || abs(q.Row-q.Col) == abs(row-col) || (q.Row+q.Col) == (row+col) {
 84 | 			return false
 85 | 		}
 86 | 	}
 87 | 	return true
 88 | }
 89 | 
 90 | // IsComplete checks if the board has N queens placed, indicating a potential solution.
 91 | func (b *Board) IsComplete() bool {
 92 | 	return len(b.Queens) == b.Size
 93 | }
 94 | 
 95 | // String provides a simple textual representation of the board.
 96 | // This can be used for basic debugging or non-visual outputs.
 97 | func (b *Board) String() string {
 98 | 	grid := make([][]rune, b.Size)
 99 | 	for i := range grid {
100 | 		grid[i] = make([]rune, b.Size)
101 | 		for j := range grid[i] {
102 | 			grid[i][j] = '.'
103 | 		}
104 | 	}
105 | 
106 | 	for _, q := range b.Queens {
107 | 		grid[q.Row][q.Col] = 'Q'
108 | 	}
109 | 
110 | 	var s string
111 | 	for _, row := range grid {
112 | 		s += string(row) + "\n"
113 | 	}
114 | 	return s
115 | }
