 11 | // MinConflictsSolver implements the Min-Conflicts heuristic algorithm for the N-Queens problem.
 12 | // This is a local search algorithm that starts with a random (usually conflicting) assignment
 13 | // and iteratively improves it by moving queens to positions that minimize conflicts.
 14 | // It's particularly efficient for finding a single solution quickly, even for very large N.
 15 | type MinConflictsSolver struct {
 16 | 	maxSteps int // Maximum number of steps before giving up
 17 | 	rand     *rand.Rand
 18 | }
 19 | 
 20 | // NewMinConflictsSolver creates a new instance of the min-conflicts solver.
 21 | func NewMinConflictsSolver() *MinConflictsSolver {
 22 | 	return &MinConflictsSolver{
 23 | 		maxSteps: 1000000, // Even higher default to handle N values up to ~15 more reliably
 24 | 		rand:     rand.New(rand.NewSource(time.Now().UnixNano())),
 25 | 	}
 26 | }
 27 | 
 28 | // Solve attempts to find a single solution for the N-Queens problem using the Min-Conflicts heuristic.
 29 | // It returns a slice containing one valid solution or an error if it fails to find one within maxSteps.
 30 | func (m *MinConflictsSolver) Solve(n int) ([]models.Solution, error) {
 31 | 	if n <= 0 {
 32 | 		return nil, errors.New("n must be positive")
 33 | 	}
 34 | 	if n <= 1 {
 35 | 		if n == 1 {
 36 | 			return []models.Solution{
 37 | 				{Queens: []models.Queen{{Row: 0, Col: 0}}},
 38 | 			}, nil
 39 | 		}
 40 | 		return []models.Solution{}, nil
 41 | 	}
 42 | 
 43 | 	// Start with a random assignment where each queen is placed in a random column of its row
 44 | 	// This ensures no row conflicts, only column and diagonal ones.
 45 | 	board := make([]int, n) // board[row] = col
 46 | 	for row := 0; row < n; row++ {
 47 | 		board[row] = m.rand.Intn(n)
 48 | 	}
 49 | 
 50 | 	// Perform the hill-climbing search
 51 | 	for step := 0; step < m.maxSteps; step++ {
 52 | 		conflictList := m.findConflictingQueens(board)
 53 | 
 54 | 		if len(conflictList) == 0 {
 55 | 			// No conflicts found, we have a solution!
 56 | 			solution := models.Solution{Queens: make([]models.Queen, n)}
 57 | 			for r := 0; r < n; r++ {
 58 | 				solution.Queens[r] = models.Queen{Row: r, Col: board[r]}
 59 | 			}
 60 | 			return []models.Solution{solution}, nil
 61 | 		}
 62 | 
 63 | 		// Pick a random queen from the conflicting ones
 64 | 		queenRow := conflictList[m.rand.Intn(len(conflictList))]
 65 | 
 66 | 		// Find the column in this queen's row that minimizes conflicts
 67 | 		bestCol := board[queenRow]
 68 | 		minConflicts := m.countConflictsForRow(queenRow, board[queenRow], board)
 69 | 
 70 | 		for col := 0; col < n; col++ {
 71 | 			if col == board[queenRow] {
 72 | 				continue // Skip the current position
 73 | 			}
 74 | 
 75 | 			conflictsAtCol := m.countConflictsForRow(queenRow, col, board)
 76 | 			if conflictsAtCol < minConflicts {
 77 | 				minConflicts = conflictsAtCol
 78 | 				bestCol = col
 79 | 			}
 80 | 		}
 81 | 
 82 | 		// Move the queen to the best position found
 83 | 		board[queenRow] = bestCol
 84 | 	}
 85 | 
 86 | 	return nil, errors.New("min-conflicts solver failed to find a solution within the maximum number of steps")
 87 | }
 88 | 
 89 | // findConflictingQueens identifies all queens that are involved in conflicts.
 90 | func (m *MinConflictsSolver) findConflictingQueens(board []int) []int {
 91 | 	n := len(board)
 92 | 	conflictFlags := make([]bool, n)
 93 | 
 94 | 	for row := 0; row < n; row++ {
 95 | 		for otherRow := row + 1; otherRow < n; otherRow++ {
 96 | 			col := board[row]
 97 | 			otherCol := board[otherRow]
 98 | 
 99 | 			// Check for column conflict
100 | 			if col == otherCol {
101 | 				conflictFlags[row] = true
102 | 				conflictFlags[otherRow] = true
103 | 			}
104 | 
105 | 			// Check for diagonal conflict
106 | 			if abs(row-otherRow) == abs(col-otherCol) {
107 | 				conflictFlags[row] = true
108 | 				conflictFlags[otherRow] = true
109 | 			}
110 | 		}
111 | 	}
112 | 
113 | 	var conflictList []int
114 | 	for row, isConflicted := range conflictFlags {
115 | 		if isConflicted {
116 | 			conflictList = append(conflictList, row)
117 | 		}
118 | 	}
119 | 
120 | 	return conflictList
121 | }
122 | 
123 | // countConflictsForRow counts how many conflicts a queen would have if placed at (row, col)
124 | // considering the current state of the board.
125 | func (m *MinConflictsSolver) countConflictsForRow(row, col int, board []int) int {
126 | 	n := len(board)
127 | 	conflicts := 0
128 | 
129 | 	for otherRow := 0; otherRow < n; otherRow++ {
130 | 		if otherRow == row {
131 | 			continue
132 | 		}
133 | 
134 | 		otherCol := board[otherRow]
135 | 
136 | 		// Check for column conflict
137 | 		if col == otherCol {
138 | 			conflicts++
139 | 		}
140 | 
141 | 		// Check for diagonal conflict
142 | 		if abs(row-otherRow) == abs(col-otherCol) {
143 | 			conflicts++
144 | 		}
145 | 	}
146 | 
147 | 	return conflicts
148 | }
149 | 
150 | // abs is a helper function for integer absolute value.
151 | func abs(x int) int {
152 | 	if x < 0 {
153 | 		return -x
154 | 	}
155 | 	return x
156 | }
157 | 
