148 | // calculateAttackHeatmap calculates which squares are under attack by existing queens.
149 | func (r *Renderer) calculateAttackHeatmap(board *models.Board) [][]int {
150 | 	n := board.Size
151 | 	heatmap := make([][]int, n)
152 | 	for i := range heatmap {
153 | 		heatmap[i] = make([]int, n)
154 | 	}
155 | 
156 | 	// For each queen, mark all squares it attacks
157 | 	for _, queen := range board.Queens {
158 | 		// Mark row
159 | 		for col := 0; col < n; col++ {
160 | 			if col != queen.Col {
161 | 				heatmap[queen.Row][col]++
162 | 			}
163 | 		}
164 | 
165 | 		// Mark column
166 | 		for row := 0; row < n; row++ {
167 | 			if row != queen.Row {
168 | 				heatmap[row][queen.Col]++
169 | 			}
170 | 		}
171 | 
172 | 		// Mark diagonals
173 | 		// Top-left to bottom-right diagonal (r - c = constant)
174 | 		// Top-right to bottom-left diagonal (r + c = constant)
175 | 		for rIdx := 0; rIdx < n; rIdx++ {
176 | 			for cIdx := 0; cIdx < n; cIdx++ {
177 | 				if rIdx == queen.Row && cIdx == queen.Col {
178 | 					continue // Skip the queen's own position
179 | 				}
180 | 
181 | 				// Check if on same diagonal
182 | 				if (rIdx-queen.Row) == (cIdx-queen.Col) || (rIdx-queen.Row) == -(cIdx-queen.Col) {
183 | 					heatmap[rIdx][cIdx]++
184 | 				}
185 | 			}
186 | 		}
187 | 	}
188 | 
189 | 	return heatmap
190 | }
191 | 
192 | // RenderMultipleBoards renders multiple solutions side by side.
193 | func (r *Renderer) RenderMultipleBoards(solutions []models.Solution) string {
194 | 	if len(solutions) == 0 {
195 | 		return "No solutions to display"
196 | 	}
197 | 
198 | 	var result strings.Builder
199 | 
200 | 	for i, solution := range solutions {
201 | 		result.WriteString(fmt.Sprintf("Solution %d:\n", i+1))
202 | 		result.WriteString(r.RenderBoard(solution))
203 | 		result.WriteString("\n\n")
204 | 	}
205 | 
206 | 	return result.String()
207 | }
