 28 | // Solve attempts to find a single solution for the N-Queens problem using the Min-Conflicts heuristic.
 29 | // It returns a slice containing one valid solution or an error if it fails to find one within maxSteps.
 30 | // This implementation includes random restarts to escape local optima.
 31 | func (m *MinConflictsSolver) Solve(n int) ([]models.Solution, error) {
 32 | 	if n <= 0 {
 33 | 		return nil, errors.New("n must be positive")
 34 | 	}
 35 | 	if n <= 1 {
 36 | 		if n == 1 {
 37 | 			return []models.Solution{
