 39 | 			}, nil
 40 | 		}
 41 | 		return []models.Solution{}, nil
 42 | 	}
 43 | 
 44 | 	// Try multiple restarts to increase the chance of finding a solution
 45 | 	numRestarts := 10
 46 | 	for restart := 0; restart < numRestarts; restart++ {
 47 | 		// Start with a random assignment where each queen is placed in a random column of its row
 48 | 		// This ensures no row conflicts, only column and diagonal ones.
 49 | 		board := make([]int, n) // board[row] = col
 50 | 		for row := 0; row < n; row++ {
 51 | 			board[row] = m.rand.Intn(n)
 52 | 		}
 53 | 
