 55 | 		stepsTaken := 0
 56 | 		for stepsTaken < m.maxSteps {
 57 | 			conflictList := m.findConflictingQueens(board)
 58 | 
 59 | 			if len(conflictList) == 0 {
 60 | 				// No conflicts found, we have a solution!
 61 | 				solution := models.Solution{Queens: make([]models.Queen, n)}
 62 | 				for r := 0; r < n; r++ {
 63 | 					solution.Queens[r] = models.Queen{Row: r, Col: board[r]}
 64 | 				}
 65 | 				return []models.Solution{solution}, nil
 66 | 			}
 67 | 
 68 | 			// Pick a random queen from the conflicting ones
 69 | 			queenRow := conflictList[m.rand.Intn(len(conflictList))]
 70 | 
 71 | 			// Find the column in this queen's row that minimizes conflicts
 72 | 			bestCol := board[queenRow]
 73 | 			minConflicts := m.countConflictsForRow(queenRow, board[queenRow], board)
 74 | 
 75 | 			for col := 0; col < n; col++ {
 76 | 				if col == board[queenRow] {
 77 | 					continue // Skip the current position
 78 | 				}
 79 | 
 80 | 				conflictsAtCol := m.countConflictsForRow(queenRow, col, board)
 81 | 				if conflictsAtCol < minConflicts {
 82 | 					minConflicts = conflictsAtCol
 83 | 					bestCol = col
 84 | 				}
 85 | 			}
 86 | 
 87 | 			// Move the queen to the best position found
 88 | 			board[queenRow] = bestCol
 89 | 			stepsTaken++
 90 | 		}
 91 | 	}
 92 | 
 93 | 	return nil, errors.New("min-conflicts solver failed to find a solution within the maximum number of steps")
 94 | }
