 96 | // findConflictingQueens identifies all queens that are involved in conflicts.
 97 | func (m *MinConflictsSolver) findConflictingQueens(board []int) []int {
 98 | 	n := len(board)
 99 | 	conflictFlags := make([]bool, n)
100 | 
101 | 	for row := 0; row < n; row++ {
102 | 		for otherRow := row + 1; otherRow < n; otherRow++ {
103 | 			col := board[row]
104 | 			otherCol := board[otherRow]
105 | 
106 | 			// Check for column conflict
107 | 			if col == otherCol {
108 | 				conflictFlags[row] = true
109 | 				conflictFlags[otherRow] = true
110 | 			}
111 | 
112 | 			// Check for diagonal conflict
113 | 			if abs(row-otherRow) == abs(col-otherCol) {
114 | 				conflictFlags[row] = true
115 | 				conflictFlags[otherRow] = true
116 | 			}
117 | 		}
118 | 	}
119 | 
120 | 	var conflictList []int
121 | 	for row, isConflicted := range conflictFlags {
122 | 		if isConflicted {
123 | 			conflictList = append(conflictList, row)
124 | 		}
125 | 	}
126 | 
127 | 	return conflictList
128 | }
129 | 
130 | // countConflictsForRow counts how many conflicts a queen would have if placed at (row, col)
131 | // considering the current state of the board.
132 | func (m *MinConflictsSolver) countConflictsForRow(row, col int, board []int) int {
133 | 	n := len(board)
134 | 	conflicts := 0
135 | 
136 | 	for otherRow := 0; otherRow < n; otherRow++ {
137 | 		if otherRow == row {
138 | 			continue
139 | 		}
140 | 
141 | 		otherCol := board[otherRow]
142 | 
143 | 		// Check for column conflict
144 | 		if col == otherCol {
145 | 			conflicts++
146 | 		}
147 | 
148 | 		// Check for diagonal conflict
149 | 		if abs(row-otherRow) == abs(col-otherCol) {
150 | 			conflicts++
151 | 		}
152 | 	}
153 | 
154 | 	return conflicts
155 | }
