165 | // SolveOne returns a single valid solution as quickly as the strategy can.
166 | func (m *MinConflictsSolver) SolveOne(n int) (models.Solution, error) {
167 | 	solutions, err := m.Solve(n)
168 | 	if err != nil {
169 | 		return models.Solution{}, err
170 | 	}
171 | 	if len(solutions) == 0 {
172 | 		return models.Solution{}, &ErrNoSolution{N: n}
173 | 	}
174 | 	return solutions[0], nil
175 | }
