 11 | // MinConflictsSolver implements the local search heuristic for N-Queens.
 12 | type MinConflictsSolver struct {
 13 | 	rng *rand.Rand
 14 | }
 15 | 
 16 | // NewMinConflictsSolver creates a new instance of the min-conflicts solver.
 17 | func NewMinConflictsSolver() *MinConflictsSolver {
 18 | 	return &MinConflictsSolver{
 19 | 		rng: rand.New(rand.NewSource(time.Now().UnixNano())),
 20 | 	}
 21 | }
 22 | 
 23 | // Solve implements the Solver interface using the Min-Conflicts heuristic.
 24 | // It streams intermediate states to the channel, allowing for visualization.
 25 | func (s *MinConflictsSolver) Solve(ctx context.Context, n int) (<-chan domain.State, error) {
 26 | 	ch := make(chan domain.State)
 27 | 
 28 | 	go func() {
 29 | 		defer close(ch)
 30 | 
 31 | 		board := domain.NewBoard(n)
 32 | 
 33 | 		// Initial random placement: one queen per row
 34 | 		for row := 0; row < n; row++ {
 35 | 			col := s.rng.Intn(n)
 36 | 			board.Queens = append(board.Queens, domain.Queen{Row: row, Col: col})
 37 | 		}
 38 | 
 39 | 		maxSteps := n * n // Empirically good upper bound
 40 | 
 41 | 		for step := 0; step < maxSteps; step++ {
 42 | 			select {
 43 | 			case <-ctx.Done():
 44 | 				return
 45 | 			default:
 46 | 			}
 47 | 
 48 | 			conflicts := board.CountConflicts()
 49 | 
 50 | 			// Send current state for visualization
 51 | 			ch <- domain.State{
 52 | 				Queens:      domain.CopyState(board.Queens),
 53 | 				Conflicts:   conflicts,
 54 | 				Narrative:   fmt.Sprintf("Step %d: Current conflicts = %d", step, conflicts),
 55 | 				Explanation: "Evaluating current board state",
 56 | 			}
 57 | 
 58 | 			if conflicts == 0 {
 59 | 				// Solution found
 60 | 				ch <- domain.State{
 61 | 					Queens:      domain.CopyState(board.Queens),
 62 | 					Conflicts:   0,
 63 | 					Narrative:   fmt.Sprintf("Solution found in %d steps!", step),
 64 | 					Explanation: "All queens placed without conflicts",
 65 | 				}
 66 | 				return
 67 | 			}
 68 | 
 69 | 			// Find a queen with conflicts to move
 70 | 			conflictedQueenIndex := s.findConflictedQueen(board)
 71 | 			if conflictedQueenIndex == -1 {
 72 | 				// This shouldn't happen if conflicts > 0, but just in case
 73 | 				continue
 74 | 			}
 75 | 
 76 | 			// Find the best column for this queen to minimize conflicts
 77 | 			bestCol := s.findBestColumnForQueen(board, conflictedQueenIndex)
 78 | 
 79 | 			// Move the queen
 80 | 			oldCol := board.Queens[conflictedQueenIndex].Col
 81 | 			board.Queens[conflictedQueenIndex].Col = bestCol
 82 | 
 83 | 			// Send state after move for visualization
 84 | 			newConflicts := board.CountConflicts()
 85 | 			ch <- domain.State{
 86 | 				Queens:      domain.CopyState(board.Queens),
 87 | 				Conflicts:   newConflicts,
 88 | 				Narrative:   fmt.Sprintf("Moved queen from (%d, %d) to (%d, %d)", conflictedQueenIndex, oldCol, conflictedQueenIndex, bestCol),
 89 | 				Explanation: fmt.Sprintf("Reduced conflicts from %d to %d by moving queen in row %d", conflicts, newConflicts, conflictedQueenIndex),
 90 | 			}
 91 | 		}
 92 | 
 93 | 		// If we reach here, we didn't find a solution within maxSteps
 94 | 		conflicts := board.CountConflicts()
 95 | 		ch <- domain.State{
 96 | 			Queens:      domain.CopyState(board.Queens),
 97 | 			Conflicts:   conflicts,
 98 | 			Narrative:   fmt.Sprintf("Failed to find solution in %d steps. Final conflicts: %d", maxSteps, conflicts),
 99 | 			Explanation: "Local search heuristic did not converge to a solution",
100 | 		}
101 | 	}()
102 | 
103 | 	return ch, nil
104 | }
