106 | // findConflictedQueen randomly selects a queen that is involved in a conflict.
107 | func (s *MinConflictsSolver) findConflictedQueen(board *domain.Board) int {
108 | 	conflictedQueens := []int{}
109 | 
110 | 	// Identify all queens that are in conflict
111 | 	for i, q1 := range board.Queens {
112 | 		inConflict := false
113 | 		for j, q2 := range board.Queens {
114 | 			if i != j {
115 | 				// Check for conflicts: same row, same col, or same diagonal
116 | 				// Row check is redundant since we place one per row
117 | 				if q1.Col == q2.Col {
118 | 					inConflict = true
119 | 					break
120 | 				}
121 | 				// Diagonal check
122 | 				rowDiff := q1.Row - q2.Row
123 | 				colDiff := q1.Col - q2.Col
124 | 				if rowDiff == colDiff || rowDiff == -colDiff {
125 | 					inConflict = true
126 | 					break
127 | 				}
128 | 			}
129 | 		}
130 | 		if inConflict {
131 | 			conflictedQueens = append(conflictedQueens, i)
132 | 		}
133 | 	}
134 | 
135 | 	if len(conflictedQueens) == 0 {
136 | 		return -1 // No conflicted queens found
137 | 	}
138 | 
139 | 	// Randomly select one of the conflicted queens
140 | 	return conflictedQueens[s.rng.Intn(len(conflictedQueens))]
141 | }
142 | 
143 | // findBestColumnForQueen finds the column for the specified queen that minimizes conflicts.
144 | func (s *MinConflictsSolver) findBestColumnForQueen(board *domain.Board, queenIndex int) int {
145 | 	currentQueen := board.Queens[queenIndex]
146 | 	bestCol := currentQueen.Col
147 | 	minConflicts := s.calculateConflictsForPosition(board, currentQueen.Row, bestCol, queenIndex)
148 | 
149 | 	// Try all possible columns for this queen
150 | 	for col := 0; col < board.N; col++ {
151 | 		if col == currentQueen.Col {
152 | 			continue // Skip current position, we already calculated it
153 | 		}
154 | 
155 | 		conflicts := s.calculateConflictsForPosition(board, currentQueen.Row, col, queenIndex)
156 | 		if conflicts < minConflicts {
157 | 			minConflicts = conflicts
158 | 			bestCol = col
159 | 		}
160 | 	}
161 | 
162 | 	return bestCol
163 | }
164 | 
165 | // calculateConflictsForPosition calculates the number of conflicts if a queen were placed at (row, col),
166 | // excluding conflicts with the queen at excludeIndex (since we're evaluating a move for that queen).
167 | func (s *MinConflictsSolver) calculateConflictsForPosition(board *domain.Board, row, col int, excludeIndex int) int {
168 | 	conflicts := 0
169 | 
170 | 	for i, q := range board.Queens {
171 | 		if i == excludeIndex {
172 | 			continue // Don't compare with the queen we're moving
173 | 		}
174 | 
175 | 		// Check for conflicts with this queen
176 | 		// Same column
177 | 		if col == q.Col {
178 | 			conflicts++
179 | 		}
180 | 		// Diagonal conflict
181 | 		rowDiff := row - q.Row
182 | 		colDiff := col - q.Col
183 | 		if rowDiff == colDiff || rowDiff == -colDiff {
184 | 			conflicts++
185 | 		}
186 | 	}
187 | 
188 | 	return conflicts
189 | }
