 44 | // CopyState creates a deep copy of the Queen slice to ensure state immutability in snapshots.
 45 | func CopyState(queens []Queen) []Queen {
 46 | 	cp := make([]Queen, len(queens))
 47 | 	copy(cp, queens)
 48 | 	return cp
 49 | }
