 51 | // IsValid checks if placing a queen at (row, col) is valid given the current queens.
 52 | func (b *Board) IsValid(row, col int) bool {
 53 | 	for _, q := range b.Queens {
 54 | 		// Check row
 55 | 		if q.Row == row {
 56 | 			return false
 57 | 		}
 58 | 		// Check column
 59 | 		if q.Col == col {
 60 | 			return false
 61 | 		}
 62 | 		// Check diagonals
 63 | 		rowDiff := q.Row - row
 64 | 		colDiff := q.Col - col
 65 | 		if rowDiff == colDiff || rowDiff == -colDiff {
 66 | 			return false
 67 | 		}
 68 | 	}
 69 | 	return true
 70 | }
