 72 | // CountConflicts calculates the total number of conflicts on the board.
 73 | // This is useful for local search heuristics like Min-Conflicts.
 74 | func (b *Board) CountConflicts() int {
 75 | 	conflicts := 0
 76 | 	for i, q1 := range b.Queens {
 77 | 		for j, q2 := range b.Queens {
 78 | 			if i != j {
 79 | 				// Row conflict
 80 | 				if q1.Row == q2.Row {
 81 | 					conflicts++
 82 | 				}
 83 | 				// Col conflict
 84 | 				if q1.Col == q2.Col {
 85 | 					conflicts++
 86 | 				}
 87 | 				// Diagonal conflict
 88 | 				rowDiff := q1.Row - q2.Row
 89 | 				colDiff := q1.Col - q2.Col
 90 | 				if rowDiff == colDiff || rowDiff == -colDiff {
 91 | 					conflicts++
 92 | 				}
 93 | 			}
 94 | 		}
 95 | 	}
 96 | 	// Each conflict is counted twice (q1 vs q2 and q2 vs q1) in this simple loop,
 97 | 	// so divide by 2 to get the actual number of unique conflict pairs.
 98 | 	return conflicts / 2
 99 | }
