  9 | // Limiter defines the standard interface for rate limiting algorithms.
 10 | type Limiter interface {
 11 | 	// Allow reports whether an event is allowed; it returns true if allowed, false otherwise.
 12 | 	Allow(ctx context.Context) (bool, error)
 13 | }
