 15 | // TokenBucketLimiter implements the Token Bucket algorithm.
 16 | type TokenBucketLimiter struct {
 17 | 	mu            sync.Mutex
 18 | 	capacity      float64
 19 | 	refillRate    float64 // tokens per second
 20 | 	currentTokens float64
 21 | 	lastRefilled  time.Time
 22 | 	now           func() time.Time
 23 | }
 24 | 
 25 | // NewTokenBucketLimiter creates a new TokenBucketLimiter instance.
 26 | func NewTokenBucketLimiter(capacity, refillRate float64) *TokenBucketLimiter {
 27 | 	defaultNow := func() time.Time { return time.Now() }
 28 | 	return &TokenBucketLimiter{
 29 | 		capacity:      capacity,
 30 | 		refillRate:    refillRate,
 31 | 		currentTokens: capacity,
 32 | 		lastRefilled:  defaultNow(),
 33 | 		now:           defaultNow,
 34 | 	}
 35 | }
 36 | 
 37 | // NewTokenBucketLimiterWithTime creates a new TokenBucketLimiter instance with a custom time function for testing.
 38 | func NewTokenBucketLimiterWithTime(capacity, refillRate float64, nowFunc func() time.Time) *TokenBucketLimiter {
 39 | 	return &TokenBucketLimiter{
 40 | 		capacity:      capacity,
 41 | 		refillRate:    refillRate,
 42 | 		currentTokens: capacity,
 43 | 		lastRefilled:  nowFunc(),
 44 | 		now:           nowFunc,
 45 | 	}
 46 | }
 47 | 
 48 | // Allow reports whether an event is allowed; it returns true if allowed, false otherwise.
 49 | func (t *TokenBucketLimiter) Allow(ctx context.Context) (bool, error) {
 50 | 	t.mu.Lock()
 51 | 	defer t.mu.Unlock()
 52 | 
 53 | 	now := t.now()
 54 | 	elapsed := now.Sub(t.lastRefilled).Seconds()
 55 | 
 56 | 	// Handle clock drift/negative elapsed time by not adding tokens
 57 | 	if elapsed > 0 {
 58 | 		t.currentTokens += elapsed * t.refillRate
 59 | 		if t.currentTokens > t.capacity {
 60 | 			t.currentTokens = t.capacity
 61 | 		}
 62 | 	}
 63 | 	t.lastRefilled = now
 64 | 
 65 | 	if t.currentTokens >= 1 {
 66 | 		t.currentTokens -= 1
 67 | 		return true, nil
 68 | 	}
 69 | 	return false, nil
 70 | }
