 72 | // SlidingWindowLimiter implements the Sliding Window Counter algorithm.
 73 | type SlidingWindowLimiter struct {
 74 | 	mu       sync.Mutex
 75 | 	limit    int           // max requests allowed per window
 76 | 	window   time.Duration // time window (e.g., 1 minute)
 77 | 	counters map[int64]int // maps timestamp to request count
 78 | }
 79 | 
 80 | // NewSlidingWindowLimiter creates a new SlidingWindowLimiter instance.
 81 | func NewSlidingWindowLimiter(limit int, window time.Duration) *SlidingWindowLimiter {
 82 | 	return &SlidingWindowLimiter{
 83 | 		limit:    limit,
 84 | 		window:   window,
 85 | 		counters: make(map[int64]int),
 86 | 	}
 87 | }
 88 | 
 89 | // Allow reports whether an event is allowed; it returns true if allowed, false otherwise.
 90 | func (s *SlidingWindowLimiter) Allow(ctx context.Context) (bool, error) {
 91 | 	s.mu.Lock()
 92 | 	defer s.mu.Unlock()
 93 | 
 94 | 	now := time.Now().Unix()
 95 | 	windowStart := now - int64(s.window.Seconds())
 96 | 
 97 | 	// Clean up old entries outside the window
 98 | 	for ts := range s.counters {
 99 | 		if ts < windowStart {
100 | 			delete(s.counters, ts)
101 | 		}
102 | 	}
103 | 
104 | 	// Calculate total requests in the current window
105 | 	total := 0
106 | 	for ts, count := range s.counters {
107 | 		if ts >= windowStart {
108 | 			total += count
109 | 		}
110 | 	}
111 | 
112 | 	// Check if we're under the limit
113 | 	if total < s.limit {
114 | 		s.counters[now]++
115 | 		return true, nil
116 | 	}
117 | 
118 | 	return false, nil
119 | }
