  8 | // BitwiseBacktrackingSolver implements the Solver interface using bitmasks.
  9 | type BitwiseBacktrackingSolver struct{}
 10 | 
 11 | func NewBitwiseBacktrackingSolver() *BitwiseBacktrackingSolver {
 12 | 	return &BitwiseBacktrackingSolver{}
 13 | }
 14 | 
 15 | // Solve returns a channel of StepBreak for visual exploration of the backtracking process.
 16 | // It finds one complete solution and yields steps along the way.
 17 | func (s *BitwiseBacktrackingSolver) Solve(ctx context.Context, n int) <-chan StepBreak {
 18 | 	ch := make(chan StepBreak)
 19 | 	go func() {
 20 | 		defer close(ch)
 21 | 		var queens []Move
 22 | 
 23 | 		var backtrack func(row int, cols int, leftDiag int, rightDiag int) bool
 24 | 		backtrack = func(row int, cols int, leftDiag int, rightDiag int) bool {
 25 | 			if ctx.Err() != nil {
 26 | 				return false
 27 | 			}
 28 | 
 29 | 			if row == n {
 30 | 				ch <- StepBreak{
 31 | 					State:       BoardState{N: n, Queens: queens},
 32 | 					Explanation: "🎉 Goal reached! All queens placed safely.",
 33 | 				}
 34 | 				return true
 35 | 			}
 36 | 
 37 | 			// Valid positions are those with bit 0 set in the combined mask of all "taken" spots
 38 | 			possibilities := (1 << uint(n)) - 1 & ^(cols|leftDiag|rightDiag)
 39 | 
 40 | 			for possibilities > 0 {
 41 | 				pbit := possibilities & -possibilities
 42 | 				colIdx := 0
 43 | 				for (1 << uint(colIdx)) != pbit {
 44 | 					colIdx++
 45 | 				}
 46 | 
 47 | 				// Step forward: Place queen
 48 | 				queens = append(queens, Move{Row: row, Col: colIdx})
 49 | 				ch <- StepBreak{
 50 | 					State:       BoardState{N: n, Queens: queens},
 51 | 					Explanation: fmt.Sprintf("Placing queen at [%d, %d].", row, colIdx),
 52 | 				}
 53 | 
 54 | 				// Recursively try next row
 55 | 				if backtrack(row+1, cols|pbit, (leftDiag|pbit)<<1, (rightDiag|pbit)>>1) {
 56 | 					return true
 57 | 				}
 58 | 
 59 | 				// Backtrack: remove current queen from slice
 60 | 				queens = queens[:len(queens)-1]
 61 | 				ch <- StepBreak{
 62 | 					State:       BoardState{N: n, Queens: queens},
 63 | 					Explanation: fmt.Sprintf("Position [%d, %d] failed! Backtracking...", row, colIdx),
 64 | 				}
 65 | 
 66 | 				// Remove the bit we just tried from possibilities
 67 | 				possibilities ^= pbit
 68 | 			}
 69 | 			return false
 70 | 		}
 71 | 
 72 | 		backtrack(0, 0, 0, 0)
 73 | 	}()
 74 | 
 75 | 	return ch
 76 | }
 77 | 
 78 | // BenchmarkSolve provides a high-performance path that returns all solutions.
 79 | func (s *BitwiseBacktrackingSolver) BenchmarkSolve(ctx context.Context, n int) ([]Solution, error) {
 80 | 	var results []Solution
 81 | 
 82 | 	var backtrack func(row int, cols int, leftDiag int, rightDiag int, currentQueens []Move)
 83 | 	backtrack = func(row int, cols int, leftDiag int, rightDiag int, currentQueens []Move) {
 84 | 		if row == n {
 85 | 			res := make([]Move, n)
 86 | 			copy(res, currentQueens)
 87 | 			results = append(results, Solution{Queens: res})
 88 | 			return
 89 | 		}
 90 | 
 91 | 		possibilities := (1 << uint(n)) - 1 & ^(cols|leftDiag|rightDiag)
 92 | 		for possibilities > 0 {
 93 | 			pbit := possibilities & -possibilities
 94 | 			colIdx := 0
 95 | 			for (1 << uint(colIdx)) != pbit {
 96 | 				colIdx++
 97 | 			}
 98 | 
 99 | 			// Pass a new slice to avoid sharing state across recursive branches
100 | 			newQueens := make([]Move, len(currentQueens)+1)
101 | 			copy(newQueens, currentQueens)
102 | 			newQueens[len(currentQueens)] = Move{Row: row, Col: colIdx}
103 | 
104 | 			backtrack(row+1, cols|pbit, (leftDiag|pbit)<<1, (rightDiag|pbit)>>1, newQueens)
105 | 
106 | 			possibilities ^= pbit
107 | 		}
108 | 	}
109 | 
110 | 	backtrack(0, 0, 0, 0, make([]Move, 0, n))
111 | 	return results, nil
112 | }
