 14 | // MinConflictsSolver implements the Solver interface using a local search heuristic.
 15 | // It starts with a random placement of queens (one per row) and then repeatedly
 16 | // picks a conflicted queen and moves it to a position in its row that minimizes conflicts.
 17 | type MinConflictsSolver struct {
 18 | 	rng *rand.Rand
 19 | }
 20 | 
 21 | func NewMinConflictsSolver() *MinConflictsSolver {
 22 | 	// Seed the random number generator
 23 | 	src := rand.NewSource(time.Now().UnixNano())
 24 | 	return &MinConflictsSolver{
 25 | 		rng: rand.New(src),
 26 | 	}
 27 | }
 28 | 
 29 | // Solve returns a channel of StepBreak for visual exploration of the min-conflicts process.
 30 | // This is more suited for finding a single solution quickly rather than all solutions.
 31 | func (s *MinConflictsSolver) Solve(ctx context.Context, n int) <-chan StepBreak {
 32 | 	ch := make(chan StepBreak)
 33 | 	go func() {
 34 | 		defer close(ch)
 35 | 
 36 | 		// Initial state: place one queen randomly in each row
 37 | 		queens := make([]Move, n)
 38 | 		for r := 0; r < n; r++ {
 39 | 			queens[r] = Move{Row: r, Col: s.rng.Intn(n)}
 40 | 		}
 41 | 
 42 | 		state := BoardState{N: n, Queens: queens}
 43 | 
 44 | 		// Report initial state
 45 | 		ch <- StepBreak{
 46 | 			State:       state,
 47 | 			Explanation: "Starting with a random placement of queens (one per row).",
 48 | 		}
 49 | 
 50 | 		maxSteps := 100 * n // Empirically good upper bound
 51 | 
 52 | 		for step := 0; step < maxSteps; step++ {
 53 | 			if ctx.Err() != nil {
 54 | 				return
 55 | 			}
 56 | 
 57 | 			conflictedQueens := s.findConflictedQueens(state)
 58 | 			if len(conflictedQueens) == 0 {
 59 | 				// No conflicts, solution found!
 60 | 				ch <- StepBreak{
 61 | 					State:       state,
 62 | 					Explanation: "🎉 No conflicts found! Solution reached.",
 63 | 				}
 64 | 				return
 65 | 			}
 66 | 
 67 | 			// Pick a random conflicted queen
 68 | 			qIndex := conflictedQueens[s.rng.Intn(len(conflictedQueens))]
 69 | 			queen := state.Queens[qIndex]
 70 | 
 71 | 			// Find the column in the queen's row with the minimum number of conflicts
 72 | 			bestCol := queen.Col
 73 | 			minConflicts := s.countConflictsForPos(state, queen.Row, bestCol)
 74 | 
 75 | 			for col := 0; col < n; col++ {
 76 | 				if col == queen.Col {
 77 | 					continue // Skip the current position
 78 | 				}
 79 | 				conflictsHere := s.countConflictsForPos(state, queen.Row, col)
 80 | 				if conflictsHere < minConflicts {
 81 | 					minConflicts = conflictsHere
 82 | 					bestCol = col
 83 | 				}
 84 | 			}
 85 | 
 86 | 			// Move the queen to the best position found
 87 | 			state.Queens[qIndex] = Move{Row: queen.Row, Col: bestCol}
 88 | 
 89 | 			ch <- StepBreak{
 90 | 				State:       state,
 91 | 				Explanation: "Moved a conflicted queen to a position with fewer conflicts.",
 92 | 			}
 93 | 
 94 | 			// Small delay to allow for cancellation via context
 95 | 			select {
 96 | 			case <-time.After(1 * time.Millisecond):
 97 | 			case <-ctx.Done():
 98 | 				return
 99 | 			}
100 | 		}
101 | 
102 | 		// If we reach here, we didn't find a solution in maxSteps
103 | 		ch <- StepBreak{
104 | 			State:       state,
105 | 			Explanation: "⚠️  Max steps reached. Did not converge to a solution.",
106 | 		}
107 | 	}()
108 | 
109 | 	return ch
110 | }
