112 | // BenchmarkSolve provides a high-performance path that returns a single solution.
113 | func (s *MinConflictsSolver) BenchmarkSolve(ctx context.Context, n int) ([]Solution, error) {
114 | 	// Start with a random placement of queens (one per row)
115 | 	queens := make([]Move, n)
116 | 	for r := 0; r < n; r++ {
117 | 		queens[r] = Move{Row: r, Col: s.rng.Intn(n)}
118 | 	}
119 | 
120 | 	maxSteps := 100 * n
121 | 
122 | 	for step := 0; step < maxSteps; step++ {
123 | 		if ctx.Err() != nil {
124 | 			return nil, ctx.Err()
125 | 		}
126 | 
127 | 		conflictedQueens := s.findConflictedQueens(BoardState{N: n, Queens: queens})
128 | 		if len(conflictedQueens) == 0 {
129 | 			// Solution found
130 | 			return []Solution{{Queens: queens}}, nil
131 | 		}
132 | 
133 | 		qIndex := conflictedQueens[s.rng.Intn(len(conflictedQueens))]
134 | 		queen := queens[qIndex]
135 | 
136 | 		bestCol := queen.Col
137 | 		minConflicts := s.countConflictsForPos(BoardState{N: n, Queens: queens}, queen.Row, bestCol)
138 | 
139 | 		for col := 0; col < n; col++ {
140 | 			if col == queen.Col {
141 | 				continue
142 | 			}
143 | 			conflictsHere := s.countConflictsForPos(BoardState{N: n, Queens: queens}, queen.Row, col)
144 | 			if conflictsHere < minConflicts {
145 | 				minConflicts = conflictsHere
146 | 				bestCol = col
147 | 			}
148 | 		}
149 | 
150 | 		queens[qIndex] = Move{Row: queen.Row, Col: bestCol}
151 | 	}
152 | 
153 | 	// Did not converge
154 | 	return nil, ErrDidNotConverge
