157 | // findConflictedQueens returns the indices of queens that are in conflict.
158 | func (s *MinConflictsSolver) findConflictedQueens(state BoardState) []int {
159 | 	conflicted := []int{}
160 | 	for i, q1 := range state.Queens {
161 | 		isSafe := true
162 | 		for j, q2 := range state.Queens {
163 | 			if i == j {
164 | 				continue // Don't compare a queen to itself
165 | 			}
166 | 			if s.isAttacking(q1, q2) {
167 | 				isSafe = false
168 | 				break
169 | 			}
170 | 		}
171 | 		if !isSafe {
172 | 			conflicted = append(conflicted, i)
173 | 		}
174 | 	}
175 | 	return conflicted
176 | }
177 | 
178 | // countConflictsForPos counts how many queens on the board would attack the given position.
179 | func (s *MinConflictsSolver) countConflictsForPos(state BoardState, row, col int) int {
180 | 	count := 0
181 | 	pos := Move{Row: row, Col: col}
182 | 	for _, q := range state.Queens {
183 | 		if s.isAttacking(pos, q) {
184 | 			count++
185 | 		}
186 | 	}
187 | 	return count
188 | }
189 | 
190 | // isAttacking checks if two queens can attack each other.
191 | func (s *MinConflictsSolver) isAttacking(q1, q2 Move) bool {
192 | 	// Same column
193 | 	if q1.Col == q2.Col {
194 | 		return true
195 | 	}
196 | 	// Same diagonal (absolute difference of rows equals absolute difference of columns)
197 | 	rowDiff := q1.Row - q2.Row
198 | 	if rowDiff < 0 {
199 | 		rowDiff = -rowDiff
200 | 	}
201 | 	colDiff := q1.Col - q2.Col
202 | 	if colDiff < 0 {
203 | 		colDiff = -colDiff
204 | 	}
205 | 	if rowDiff == colDiff {
206 | 		return true
207 | 	}
208 | 	return false
209 | }
